def words_in_sentence(sentence):
    assert isinstance(sentence, str), "invalid inputs"
    assert 1 <= len(sentence) <= 100, "invalid inputs"
    assert "  " not in sentence, "invalid inputs"
    assert all(word.isalpha() for word in sentence.split(" ")), "invalid inputs"

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        d = 3
        while d * d <= n:
            if n % d == 0:
                return False
            d += 2
        return True

    words = sentence.split(" ")
    selected = [w for w in words if is_prime(len(w))]
    return " ".join(selected)

def specialFilter(nums):
    assert type(nums) == list, "invalid inputs"
    assert all(type(x) == int for x in nums), "invalid inputs"

    count = 0
    for n in nums:
        if n <= 10:
            continue
        s = str(abs(n))
        first = ord(s[0]) - 48
        last = ord(s[-1]) - 48
        if (first & 1) and (last & 1):
            count += 1
    return count

def bf(planet1, planet2):
    planets = ("Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune")
    try:
        i1 = planets.index(planet1)
        i2 = planets.index(planet2)
    except ValueError:
        return ()
    if i1 == i2:
        return ()
    lo, hi = (i1, i2) if i1 < i2 else (i2, i1)
    return planets[lo + 1:hi]

def sorted_list_sum(lst):
    assert type(lst) == list, "invalid inputs"
    assert all(type(x) == str for x in lst), "invalid inputs"
    even_len_words = [s for s in lst if len(s) % 2 == 0]
    return sorted(even_len_words, key=lambda s: (len(s), s))

def string_sequence(n: int) -> str:
    assert type(n) == int, "invalid inputs"
    assert n >= 0, "invalid inputs"
    return " ".join(map(str, range(n + 1)))

def x_or_y(n, x, y):
    assert type(n) == int, "invalid inputs"  # $_CONTRACT_$
    if n < 2:
        return y
    if n == 2 or n == 3:
        return x
    if n % 2 == 0 or n % 3 == 0:
        return y
    i = 5
    step = 2
    while i * i <= n:
        if n % i == 0:
            return y
        i += step
        step = 6 - step
    return x

def double_the_difference(lst):
    assert type(lst) == list, "invalid inputs"
    total = 0
    for x in lst:
        if isinstance(x, bool):
            continue
        if isinstance(x, int):
            if x > 0 and (x % 2 == 1):
                total += x * x
        elif isinstance(x, float):
            if x > 0 and x.is_integer():
                xi = int(x)
                if xi % 2 == 1:
                    total += xi * xi
    return total

def Strongest_Extension(class_name, extensions):
    best_ext = extensions[0]
    best_strength = sum(1 if c.isupper() else -1 if c.islower() else 0 for c in best_ext)

    for ext in extensions[1:]:
        strength = sum(1 if c.isupper() else -1 if c.islower() else 0 for c in ext)
        if strength > best_strength:
            best_strength = strength
            best_ext = ext

    return f"{class_name}.{best_ext}"

def cycpattern_check(a, b):
    assert isinstance(a, str) and isinstance(b, str), "invalid inputs"
    if b == "":
        return True
    if len(b) > len(a):
        return False
    bb = b + b
    n = len(b)
    for i in range(n):
        if bb[i:i + n] in a:
            return True
    return False

def even_odd_count(num):
    assert type(num) == int, "invalid inputs"
    n = abs(num)
    if n == 0:
        return (1, 0)
    even = odd = 0
    while n:
        d = n % 10
        if d % 2 == 0:
            even += 1
        else:
            odd += 1
        n //= 10
    return (even, odd)

def right_angle_triangle(a, b, c):
    assert type(a) in [int, float] and type(b) in [int, float] and type(c) in [int, float], "invalid inputs"
    assert a > 0 and b > 0 and c > 0, "invalid inputs"

    sides = sorted([float(a), float(b), float(c)])
    x, y, z = sides

    if x + y <= z:
        return False

    eps = 1e-9
    return abs((x * x + y * y) - (z * z)) <= eps * max(1.0, z * z)

def find_max(words):
    best_word = None
    best_unique = -1
    for w in words:
        u = len(set(w))
        if u > best_unique:
            best_unique = u
            best_word = w
        elif u == best_unique:
            if w < best_word:
                best_word = w
    return best_word

def count_distinct_characters(string: str) -> int:
    assert isinstance(string, str), "invalid inputs"  # $_CONTRACT_$
    return len(set(string.casefold()))

def solve(s):
    assert isinstance(s, str), "invalid inputs"
    has_letter = any(c.isalpha() for c in s)
    if not has_letter:
        return s[::-1]
    return "".join(c.swapcase() if c.isalpha() else c for c in s)

import hashlib

def string_to_md5(text):
    assert isinstance(text, str), "invalid inputs"
    if text == "":
        return None
    return hashlib.md5(text.encode("utf-8")).hexdigest()

from typing import List

def parse_music(music_string: str) -> List[int]:
    assert isinstance(music_string, str), "invalid inputs"  # $_CONTRACT_$
    assert music_string == "" or all(map(lambda x: x in ["o", "o|", ".|"], music_string.split(" "))), "invalid inputs"  # $_CONTRACT_$
    if music_string == "":
        return []
    mapping = {"o": 4, "o|": 2, ".|": 1}
    return [mapping[token] for token in music_string.split(" ")]

