    return False

from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    groups: List[str] = []
    curr: List[str] = []
    depth = 0

    for ch in paren_string:
        if ch == " ":
            continue
        if ch == "(":
            if depth == 0:
                curr = []
            curr.append(ch)
            depth += 1
        else:  # ch == ")"
            curr.append(ch)
            depth -= 1
            if depth == 0:
                groups.append("".join(curr))

    return groups

