def encode(message):
    assert type(message) == str, "invalid inputs"
    assert all(ch == " " or ch.isalpha() for ch in message), "invalid inputs"

    trans = {'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
             'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'}

    out = []
    for ch in message:
        if ch == " ":
            out.append(ch)
            continue
        swapped = ch.swapcase()
        out.append(trans.get(swapped, swapped))
    return "".join(out)

def skjkasdkd(lst):
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        if n % 3 == 0:
            return n == 3
        r = int(n ** 0.5)
        f = 5
        while f <= r:
            if n % f == 0 or n % (f + 2) == 0:
                return False
            f += 6
        return True

    max_prime = None
    for x in lst:
        if is_prime(x):
            if max_prime is None or x > max_prime:
                max_prime = x

    return sum(int(c) for c in str(max_prime))

