def next_smallest_palindrome(num: int) -> int:
    assert isinstance(num, int), "invalid inputs"
    assert num >= 0, "invalid inputs"

    s = str(num)
    n = len(s)

    # Mirror left to right
    left = s[: (n + 1) // 2]
    if n % 2 == 0:
        pal = left + left[::-1]
    else:
        pal = left + left[:-1][::-1]

    if int(pal) > num:
        return int(pal)

    # Increment the middle (left half including center) and mirror again
    inc = str(int(left) + 1)
    if len(inc) > len(left):
        return int("1" + ("0" * (n - 1)) + "1")

    if n % 2 == 0:
        pal2 = inc + inc[::-1]
    else:
        pal2 = inc + inc[:-1][::-1]
    return int(pal2)

