def eulerian_num(n, m):
    assert isinstance(n, int), "invalid inputs"
    assert isinstance(m, int), "invalid inputs"
    assert n >= 0, "invalid inputs"
    assert m >= 0, "invalid inputs"

    if m >= n:
        return 0
    if n == 0:
        return 1 if m == 0 else 0
    if m == 0:
        return 1
    if m == n - 1:
        return 1

    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        new = [0] * n
        upper = min(i, m)
        for j in range(0, upper + 1):
            val = (j + 1) * dp[j]
            if j > 0:
                val += (i - j + 1) * dp[j - 1]
            new[j] = val
        dp = new
    return dp[m]

