def merge_sorted_list(num1, num2, num3):
    assert isinstance(num1, list), "invalid inputs"
    assert isinstance(num2, list), "invalid inputs"
    assert isinstance(num3, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in num1), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in num2), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in num3), "invalid inputs"

    a = sorted(num1)
    b = sorted(num2)
    c = sorted(num3)

    i = j = k = 0
    res = []
    la, lb, lc = len(a), len(b), len(c)

    while i < la or j < lb or k < lc:
        va = a[i] if i < la else None
        vb = b[j] if j < lb else None
        vc = c[k] if k < lc else None

        if va is None:
            if vb is None:
                res.append(vc)
                k += 1
            elif vc is None:
                res.append(vb)
                j += 1
            else:
                if vb <= vc:
                    res.append(vb)
                    j += 1
                else:
                    res.append(vc)
                    k += 1
        elif vb is None:
            if vc is None:
                res.append(va)
                i += 1
            else:
                if va <= vc:
                    res.append(va)
                    i += 1
                else:
                    res.append(vc)
                    k += 1
        elif vc is None:
            if va <= vb:
                res.append(va)
                i += 1
            else:
                res.append(vb)
                j += 1
        else:
            if va <= vb and va <= vc:
                res.append(va)
                i += 1
            elif vb <= va and vb <= vc:
                res.append(vb)
                j += 1
            else:
                res.append(vc)
                k += 1

    return res

