def search(arr):
    assert isinstance(arr, list), "invalid inputs"
    assert all(isinstance(x, int) for x in arr), "invalid inputs"
    assert all(a <= b for a, b in zip(arr, arr[1:])), "invalid inputs"
    n = len(arr)
    if n == 0:
        return None
    if n == 1:
        return arr[0]
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid % 2 == 1:
            mid -= 1
        if mid + 1 < n and arr[mid] == arr[mid + 1]:
            lo = mid + 2
        else:
            hi = mid
    return arr[lo]

def amicable_numbers_sum(limit: int) -> int:
    assert isinstance(limit, int), "invalid inputs"
    assert limit >= 1, "invalid inputs"

    if limit < 2:
        return 0

    def sum_proper_divisors_upto(n: int):
        spd = [0] * (n + 1)
        if n >= 1:
            spd[1] = 0
        for d in range(1, n // 2 + 1):
            for m in range(d * 2, n + 1, d):
                spd[m] += d
        return spd

    spd = sum_proper_divisors_upto(limit)
    total = 0
    for a in range(2, limit + 1):
        b = spd[a]
        if b != a and 1 <= b <= limit and spd[b] == a:
            total += a
    return total

