def magic_square_test(my_matrix):
    assert isinstance(my_matrix, list), "invalid inputs"
    assert len(my_matrix) > 0, "invalid inputs"
    assert all(isinstance(row, list) for row in my_matrix), "invalid inputs"
    assert len(my_matrix[0]) > 0, "invalid inputs"
    assert all(len(row) == len(my_matrix[0]) for row in my_matrix), "invalid inputs"
    assert all(isinstance(item, (int, float)) for row in my_matrix for item in row), "invalid inputs"

    rows = len(my_matrix)
    cols = len(my_matrix[0])
    if rows != cols:
        return False

    n = rows
    target = sum(my_matrix[0])

    for r in range(1, n):
        if sum(my_matrix[r]) != target:
            return False

    for c in range(n):
        if sum(my_matrix[r][c] for r in range(n)) != target:
            return False

    if sum(my_matrix[i][i] for i in range(n)) != target:
        return False
    if sum(my_matrix[i][n - 1 - i] for i in range(n)) != target:
        return False

    return True

