def pancake_sort(nums):
    assert isinstance(nums, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in nums), "invalid inputs"

    a = list(nums)
    n = len(a)

    def flip(k):
        i, j = 0, k - 1
        while i < j:
            a[i], a[j] = a[j], a[i]
            i += 1
            j -= 1

    for size in range(n, 1, -1):
        max_idx = 0
        for i in range(1, size):
            if a[i] > a[max_idx]:
                max_idx = i
        if max_idx == size - 1:
            continue
        if max_idx != 0:
            flip(max_idx + 1)
        flip(size)

    return a

