def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    def egcd(p, q):
        old_r, r = p, q
        old_s, s = 1, 0
        old_t, t = 0, 1
        while r != 0:
            qv = old_r // r
            old_r, r = r, old_r - qv * r
            old_s, s = s, old_s - qv * s
            old_t, t = t, old_t - qv * t
        g = old_r
        if g < 0:
            g, old_s, old_t = -g, -old_s, -old_t
        return g, old_s, old_t

    if a == 0:
        if n % b != 0:
            return None
        return (0, n // b)

    if b == 0:
        if n % a != 0:
            return None
        return (n // a, 0)

    g, x0, y0 = egcd(a, b)
    if n % g != 0:
        return None

    k = n // g
    x = x0 * k
    y = y0 * k
    return (x, y)

