import math

def is_woodall(x):
    assert isinstance(x, (int, float)), "invalid inputs"
    if isinstance(x, bool):
        return False
    if isinstance(x, float):
        if not math.isfinite(x) or not x.is_integer():
            return False
        x = int(x)
    if x <= 0:
        return False

    n = x
    if n % 2 == 0:
        return False
    n1 = n + 1
    if n1 % 2 != 0:
        return False

    m = n1 // 2  # m = k * 2^k
    if m == 0:
        return False

    found = False
    mm = m
    k = 0
    while mm % 2 == 0:
        mm //= 2
        k += 1
        if mm == k:
            found = True
            break
    if not found:
        if mm == 0:
            return False
        # handle case where no factors of 2 were removed; k=0 can't satisfy since k>=1
        return False
    return True

