from functools import lru_cache

def get_total_number_of_sequences(m, n):
    assert isinstance(m, int) and m > 0, "invalid inputs"
    assert isinstance(n, int) and n > 0, "invalid inputs"

    @lru_cache(maxsize=None)
    def count(prev, remaining):
        if remaining == 0:
            return 1
        start = max(1, 2 * prev)
        if start > m:
            return 0
        total = 0
        for x in range(start, m + 1):
            total += count(x, remaining - 1)
        return total

    total = 0
    for first in range(1, m + 1):
        total += count(first, n - 1)
    return total

