import math

def next_Perfect_Square(N):
    assert isinstance(N, (int, float)), "invalid inputs"
    if isinstance(N, float):
        if not math.isfinite(N):
            raise ValueError("invalid inputs")
        if N.is_integer():
            N = int(N)
        else:
            root = math.sqrt(N)
            k = math.floor(root)
            return (k + 1) * (k + 1)

    if N < 0:
        return 0
    root = int(math.isqrt(int(N)))
    if root * root <= N:
        root += 1
    return root * root

def max_sum(arr):
    assert isinstance(arr, list), "invalid inputs"
    assert len(arr) > 0, "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in arr), "invalid inputs"

    n = len(arr)
    inc = arr[:]  # max sum increasing subsequence ending at i
    dec = arr[:]  # max sum decreasing subsequence starting at i

    for i in range(n):
        ai = arr[i]
        best = ai
        for j in range(i):
            if arr[j] < ai:
                s = inc[j] + ai
                if s > best:
                    best = s
        inc[i] = best

    for i in range(n - 1, -1, -1):
        ai = arr[i]
        best = ai
        for j in range(n - 1, i, -1):
            if arr[j] < ai:
                s = dec[j] + ai
                if s > best:
                    best = s
        dec[i] = best

    best_total = inc[0] + dec[0] - arr[0]
    for i in range(1, n):
        total = inc[i] + dec[i] - arr[i]
        if total > best_total:
            best_total = total
    return best_total

def lps(str1):
    assert isinstance(str1, str), "invalid inputs"
    n = len(str1)
    if n == 0:
        return 0

    prev = [0] * n
    curr = [0] * n

    for i in range(n - 1, -1, -1):
        curr[i] = 1
        for j in range(i + 1, n):
            if str1[i] == str1[j]:
                curr[j] = 2 + (prev[j - 1] if j - 1 >= 0 else 0)
            else:
                a = prev[j]
                b = curr[j - 1]
                curr[j] = a if a >= b else b
        prev, curr = curr, prev

    return prev[n - 1]

