def count_Primes_nums(n: int) -> int:
    assert isinstance(n, int) and n >= 0, "invalid inputs"
    if n <= 2:
        return 0
    sieve = bytearray(b"\x01") * n
    sieve[0:2] = b"\x00\x00"
    limit = int(n ** 0.5) + 1
    for p in range(2, limit):
        if sieve[p]:
            start = p * p
            step = p
            sieve[start:n:step] = b"\x00" * (((n - 1 - start) // step) + 1)
    return int(sum(sieve))

