def newman_prime(n):
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"

    def is_prime(x):
        if x < 2:
            return False
        if x % 2 == 0:
            return x == 2
        if x % 3 == 0:
            return x == 3
        i = 5
        w = 2
        while i * i <= x:
            if x % i == 0:
                return False
            i += w
            w = 6 - w
        return True

    # Newman–Shanks–Williams numbers: S_0=1, S_1=1, S_n=2*S_{n-1}+S_{n-2}
    # Candidate primes are S_n for n>=2 (sequence starts: 1,1,3,7,17,41,99,239,577,...)
    count = 0
    a, b = 1, 1  # S_0, S_1
    k = 1
    while True:
        k += 1
        a, b = b, 2 * b + a  # advance to S_k in b
        if is_prime(b):
            if count == n:
                return b
            count += 1

