def max_sub_array_sum_repeated(a, n, k):
    assert isinstance(a, list), "invalid inputs"
    assert len(a) > 0, "invalid inputs"
    assert all(isinstance(item, (int, float)) for item in a), "invalid inputs"
    assert isinstance(n, int) and n == len(a), "invalid inputs"
    assert isinstance(k, int) and k >= 0, "invalid inputs"

    if k == 0:
        return 0

    def kadane(arr):
        best = arr[0]
        cur = arr[0]
        for x in arr[1:]:
            cur = x if cur + x < x else cur + x
            best = best if best > cur else cur
        return best

    total = sum(a)

    max_prefix = a[0]
    s = 0
    for x in a:
        s += x
        if s > max_prefix:
            max_prefix = s

    max_suffix = a[-1]
    s = 0
    for x in reversed(a):
        s += x
        if s > max_suffix:
            max_suffix = s

    best_one = kadane(a)
    if k == 1:
        return best_one

    best_two = kadane(a + a)
    if total > 0:
        best_k = max_suffix + total * (k - 2) + max_prefix
        return max(best_two, best_k, best_one)
    else:
        return max(best_two, best_one)

