from typing import List, Union, Any

def flatten_list(list1: List[Any]) -> List[Union[int, float]]:
    result: List[Union[int, float]] = []
    stack = [iter(list1)]
    while stack:
        it = stack[-1]
        try:
            item = next(it)
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, list):
            stack.append(iter(item))
        else:
            result.append(item)
    return result

from collections import defaultdict

def max_aggregate(stdata):
    assert isinstance(stdata, list), "invalid inputs"
    assert all(isinstance(x, tuple) for x in stdata), "invalid inputs"
    assert all(len(x) == 2 for x in stdata), "invalid inputs"
    assert all(isinstance(x[1], (int, float)) for x in stdata), "invalid inputs"

    totals = defaultdict(float)
    for name, value in stdata:
        totals[name] += value

    if not totals:
        return (None, 0)

    max_name, max_total = None, None
    for name, total in totals.items():
        if max_total is None or total > max_total:
            max_name, max_total = name, total

    if isinstance(max_total, float) and max_total.is_integer():
        max_total = int(max_total)

    return (max_name, max_total)

def is_not_prime(n: int) -> bool:
    assert isinstance(n, int), "invalid inputs"
    assert n > 0, "invalid inputs"

    if n == 1:
        return True
    if n == 2 or n == 3:
        return False
    if n % 2 == 0 or n % 3 == 0:
        return True
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return True
        i += 6
    return False

