def max_Product(arr):
    assert isinstance(arr, list), "invalid inputs"
    assert len(arr) >= 2, "invalid inputs"
    assert all(isinstance(i, int) for i in arr), "invalid inputs"

    max1 = max2 = None
    min1 = min2 = None

    for x in arr:
        if max1 is None or x > max1:
            max2 = max1
            max1 = x
        elif max2 is None or x > max2:
            max2 = x

        if min1 is None or x < min1:
            min2 = min1
            min1 = x
        elif min2 is None or x < min2:
            min2 = x

    prod_max = max1 * max2
    prod_min = min1 * min2

    if prod_min > prod_max:
        a, b = min1, min2
    else:
        a, b = max2, max1

    return (a, b) if a <= b else (b, a)

