def cal_sum(n):
    assert isinstance(n, int), "invalid inputs"
    if n < 0:
        return 0

    # Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(n)=P(n-2)+P(n-3)
    if n == 0:
        return 3
    if n == 1:
        return 3
    if n == 2:
        return 5

    p0, p1, p2 = 3, 0, 2
    total = p0 + p1 + p2
    for _ in range(3, n + 1):
        p3 = p1 + p0
        total += p3
        p0, p1, p2 = p1, p2, p3
    return total

