def sumofFactors(n: int) -> int:
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if a % 2 == 0:
                total += a
            if b != a and b % 2 == 0:
                total += b
        i += 1
    return total

