    assert all(isinstance(x, (int, float)) for x in arr), "invalid inputs"
    assert len(arr) > 0, "invalid inputs"

    n = len(arr)
    dp = [0] * n
    best = None

    for i in range(n):
        dp[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                prod = dp[j] * arr[i]
                if prod > dp[i]:
                    dp[i] = prod
        if best is None or dp[i] > best:
            best = dp[i]

    return best

