def max_sub_array_sum(a, size):
    assert isinstance(a, list), "invalid inputs"
    assert isinstance(size, int), "invalid inputs"
    assert size <= len(a), "invalid inputs"

    if size <= 0:
        return 0

    max_ending_here = a[0]
    max_so_far = a[0]

    for i in range(1, size):
        x = a[i]
        if max_ending_here + x < x:
            max_ending_here = x
        else:
            max_ending_here += x
        if max_ending_here > max_so_far:
            max_so_far = max_ending_here

    return max_so_far

