def last_Digit_Factorial(n):
    assert isinstance(n, (int, float)), "invalid inputs"
    assert n >= 0, "invalid inputs"
    if isinstance(n, float):
        if not math.isfinite(n) or not n.is_integer():
            raise AssertionError("invalid inputs")
        n = int(n)
    else:
        n = int(n)

    if n == 0 or n == 1:
        return 1
    if n >= 5:
        return 0
    res = 1
    for i in range(2, n + 1):
        res = (res * i) % 10
    return res

