def extract_even(test_tuple):
    def is_even_number(x):
        if isinstance(x, bool):
            return False
        if isinstance(x, int):
            return x % 2 == 0
        if isinstance(x, float):
            if not x.is_integer():
                return False
            return int(x) % 2 == 0
        return False

    def helper(obj):
        if isinstance(obj, tuple):
            res = []
            for item in obj:
                processed = helper(item)
                if processed is None:
                    continue
                res.append(processed)
            return tuple(res)
        else:
            return obj if is_even_number(obj) else None

    return helper(test_tuple)

