import math

def perfect_squares(a, b):
    assert isinstance(a, int), "invalid inputs"
    assert isinstance(b, int), "invalid inputs"
    lo = min(a, b)
    hi = max(a, b)
    if hi < 0:
        return []
    start = 0 if lo <= 0 else math.isqrt(lo)
    if start * start < lo:
        start += 1
    end = math.isqrt(hi)
    return [i * i for i in range(start, end + 1)]

