def get_ludic(n):
    assert isinstance(n, int), "invalid inputs"
    assert n > 0, "invalid inputs"

    candidates = list(range(2, n + 1))
    ludics = [1]

    while candidates:
        p = candidates[0]
        ludics.append(p)
        if p > len(candidates):
            break
        new_candidates = []
        for i, v in enumerate(candidates, start=1):
            if i % p != 0:
                new_candidates.append(v)
        candidates = new_candidates

    return ludics

