def prime_num(num: int) -> bool:
    assert isinstance(num, int), "invalid inputs"
    if num < 2:
        return False
    if num in (2, 3):
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    step = 2
    while i * i <= num:
        if num % i == 0:
            return False
        i += step
        step = 6 - step
    return True

