def largest_subset(a):
    assert isinstance(a, list), "invalid inputs"
    assert len(a) >= 2, "invalid inputs"
    assert all(isinstance(el, (int, float)) for el in a), "invalid inputs"

    vals = sorted(a)
    n = len(vals)

    def divides(x, y):
        if x == 0 or y == 0:
            return x == y == 0
        if isinstance(x, float) or isinstance(y, float):
            q = y / x
            return abs(q - round(q)) <= 1e-12
        return y % x == 0

    dp = [1] * n
    for i in range(n):
        best = 1
        yi = vals[i]
        for j in range(i):
            if divides(vals[j], yi):
                cand = dp[j] + 1
                if cand > best:
                    best = cand
        dp[i] = best

    return max(dp)

def get_median(arr1, arr2, n):
    assert isinstance(arr1, list), "invalid inputs"
    assert isinstance(arr2, list), "invalid inputs"
    assert 0 <= n <= min(len(arr1), len(arr2)), "invalid inputs"
    assert all(isinstance(el, (int, float)) for el in arr1 + arr2), "invalid inputs"
    assert all(x <= y for x, y in zip(arr1[0:n], arr1[1:n])), "invalid inputs"
    assert all(x <= y for x, y in zip(arr2[0:n], arr2[1:n])), "invalid inputs"

    if n == 0:
        return 0.0

    a = arr1[:n]
    b = arr2[:n]

    if n == 1:
        return (a[0] + b[0]) / 2.0
    if n == 2:
        return (max(a[0], b[0]) + min(a[1], b[1])) / 2.0

    def median_of_sorted(x):
        m = len(x)
        if m % 2 == 1:
            return float(x[m // 2])
        return (x[m // 2 - 1] + x[m // 2]) / 2.0

    m1 = median_of_sorted(a)
    m2 = median_of_sorted(b)

    if m1 == m2:
        return float(m1)

    if m1 < m2:
        if n % 2 == 0:
            return get_median(a[n // 2 - 1 :], b[: n // 2 + 1], n - (n // 2 - 1))
        else:
            return get_median(a[n // 2 :], b[: n // 2 + 1], n - n // 2)
    else:
        if n % 2 == 0:
            return get_median(a[: n // 2 + 1], b[n // 2 - 1 :], n - (n // 2 - 1))
        else:
            return get_median(a[: n // 2 + 1], b[n // 2 :], n - n // 2)

