def pair_xor_Sum(arr, n):
    assert isinstance(arr, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in arr), "invalid inputs"
    assert n <= len(arr), "invalid inputs"

    a = []
    for x in arr[:n]:
        if isinstance(x, float):
            if not x.is_integer():
                raise AssertionError("invalid inputs")
            x = int(x)
        a.append(int(x))

    total = 0
    max_bits = 0
    for v in a:
        if v < 0:
            raise AssertionError("invalid inputs")
        if v.bit_length() > max_bits:
            max_bits = v.bit_length()

    for bit in range(max_bits + 1):
        ones = 0
        mask = 1 << bit
        for v in a:
            if v & mask:
                ones += 1
        zeros = n - ones
        total += ones * zeros * mask

    return total

def heap_sort(iterable):
    assert isinstance(iterable, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in iterable), "invalid inputs"

    a = list(iterable)
    n = len(a)

    def sift_down(start, end):
        root = start
        while True:
            child = 2 * root + 1
            if child > end:
                break
            if child + 1 <= end and a[child] < a[child + 1]:
                child += 1
            if a[root] < a[child]:
                a[root], a[child] = a[child], a[root]
                root = child
            else:
                break

    for start in range((n - 2) // 2, -1, -1):
        sift_down(start, n - 1)

    for end in range(n - 1, 0, -1):
        a[0], a[end] = a[end], a[0]
        sift_down(0, end - 1)

    return a

