    assert all(isinstance(item, (int, float)) for item in A), "invalid inputs"  # $_CONTRACT_$
    n = len(A)
    if n <= 2:
        return True

    nondecreasing = True
    nonincreasing = True

    for i in range(1, n):
        if A[i] < A[i - 1]:
            nondecreasing = False
        if A[i] > A[i - 1]:
            nonincreasing = False
        if not nondecreasing and not nonincreasing:
