def sum_in_range(l, r):
    assert isinstance(l, int), "invalid inputs"
    assert isinstance(r, int), "invalid inputs"
    assert 0 <= l <= r, "invalid inputs"

    if r < 1:
        return 0
    l = max(l, 1)

    if l % 2 == 0:
        l += 1
    if r % 2 == 0:
        r -= 1
    if l > r:
        return 0

    n = (r - l) // 2 + 1
    return n * (l + r) // 2

