def test_three_equal(x, y, z):
    assert isinstance(x, int), "invalid inputs"
    assert isinstance(y, int), "invalid inputs"
    assert isinstance(z, int), "invalid inputs"
    if x == y == z:
        return 3
    if x == y or x == z or y == z:
        return 2
    return 0

def is_perfect_square(n: int) -> bool:
    assert isinstance(n, int), "invalid inputs"
    if n < 0:
        return False
    if n < 2:
        return True
    x = n
    while True:
        y = (x + n // x) // 2
        if y >= x:
            break
        x = y
    return x * x == n

def is_product_even(arr):
    assert isinstance(arr, list), "invalid inputs"
    assert len(arr) > 0, "invalid inputs"
    assert all(isinstance(x, int) for x in arr), "invalid inputs"
    return any((x & 1) == 0 for x in arr)

def max_sum_list(lists):
    assert isinstance(lists, list), "invalid inputs"
    assert all(isinstance(x, list) for x in lists), "invalid inputs"
    assert all(all(isinstance(y, (int, float)) for y in x) for x in lists), "invalid inputs"

    if not lists:
        return []

    return max(lists, key=sum)

def max_run_uppercase(test_str: str) -> int:
    assert isinstance(test_str, str), "invalid inputs"
    assert len(test_str) > 0, "invalid inputs"

    max_run = 0
    current = 0
    for ch in test_str:
        if 'A' <= ch <= 'Z':
            current += 1
            if current > max_run:
                max_run = current
        else:
            current = 0
    return max_run

