def closest_num(N):
    assert isinstance(N, int), "invalid inputs"
    return N - 1 if N > 0 else N + 1

def find_Rotations(s: str) -> int:
    assert isinstance(s, str), "invalid inputs"
    assert len(s) > 0, "invalid inputs"

    n = len(s)
    lps = [0] * n
    j = 0
    for i in range(1, n):
        while j > 0 and s[i] != s[j]:
            j = lps[j - 1]
        if s[i] == s[j]:
            j += 1
            lps[i] = j

    p = n - lps[-1]
    if p != 0 and n % p == 0:
        return p
    return n

