def is_undulating(n: int) -> bool:
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"
    s = str(n)
    if len(s) < 3:
        return False
    a, b = s[0], s[1]
    if a == b:
        return False
    for i, ch in enumerate(s):
        if ch != (a if i % 2 == 0 else b):
            return False
    return True

def power(a, b):
    assert isinstance(a, (int, float)), "invalid inputs"
    assert isinstance(b, int), "invalid inputs"

    if b == 0:
        return 1
    if b < 0:
        if a == 0:
            raise ZeroDivisionError("0 cannot be raised to a negative power")
        return 1 / power(a, -b)

    result = 1
    base = a
    exp = b
    while exp > 0:
        if exp & 1:
            result *= base
        base *= base
        exp >>= 1
    return result

def Find_Min_Length(lst):
    assert isinstance(lst, list), "invalid inputs"
    assert len(lst) > 0, "invalid inputs"
    assert all(isinstance(item, list) for item in lst), "invalid inputs"
    return min(len(item) for item in lst)

def frequency_lists(list1):
    def is_hashable(obj):
        try:
            hash(obj)
            return True
        except TypeError:
            return False

    assert isinstance(list1, list), "invalid inputs"
    assert len(list1) > 0, "invalid inputs"
    assert all(isinstance(item, list) for item in list1), "invalid inputs"
    assert all(is_hashable(item) for sublist in list1 for item in sublist), "invalid inputs"

    freq = {}
    for sublist in list1:
        for item in sublist:
            freq[item] = freq.get(item, 0) + 1
    return freq

import math

def multiply_num(numbers):
    assert isinstance(numbers, (tuple, list)), "invalid inputs"
    assert len(numbers) > 0, "invalid inputs"
    assert all(isinstance(item, (int, float)) for item in numbers), "invalid inputs"
    product = 1.0
    for x in numbers:
        product *= x
    return product / len(numbers)

def decimal_to_binary(n: int) -> str:
    assert isinstance(n, int), "invalid inputs"
    if n == 0:
        return "0"
    sign = ""
    if n < 0:
        sign = "-"
        n = -n
    return sign + bin(n)[2:]

from typing import List


def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ""
    depth = 0

    for char in paren_string:
        if char == ' ':
            continue

        current_group += char

        if char == '(':
            depth += 1
        elif char == ')':
            depth -= 1

        if depth == 0:
            result.append(current_group)
            current_group = ""

    return result

def words_string(s):
    import re
    return re.findall(r'[^\s,]+', s)

def choose_num(x, y):
    if x > y:
        return -1

    if y % 2 == 0:
        return y
    elif y - 1 >= x:
        return y - 1
    else:
        return -1

def rounded_avg(n, m):
    if n > m:
        return -1

    total = sum(range(n, m + 1))
    count = m - n + 1
    avg = total / count
    rounded = round(avg)

    return bin(rounded)

def unique_digits(x):
    result = []
    for num in x:
        has_even_digit = False
        temp = num
        while temp > 0:
            digit = temp % 10
            if digit % 2 == 0:
                has_even_digit = True
                break
            temp //= 10
        if not has_even_digit:
            result.append(num)
    return sorted(result)

def f(n):
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            factorial = 1
            for j in range(1, i + 1):
                factorial *= j
            result.append(factorial)
        else:
            sum_nums = sum(range(1, i + 1))
            result.append(sum_nums)
    return result

def even_odd_palindrome(n):
    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def count_nums(arr):
    def digit_sum(n):
        if n == 0:
            return 0

        if n > 0:
            return sum(int(digit) for digit in str(n))
        else:
            str_n = str(abs(n))
            first_digit = -int(str_n[0])
            rest_digits = sum(int(digit) for digit in str_n[1:])
            return first_digit + rest_digits

    count = 0
    for num in arr:
        if digit_sum(num) > 0:
            count += 1

    return count

def move_one_ball(arr):
    if not arr:
        return True

    sorted_arr = sorted(arr)

    for i in range(len(arr)):
        if arr == sorted_arr:
            return True
        arr = [arr[-1]] + arr[:-1]

    return False

def exchange(lst1, lst2):
    even_count_total = sum(1 for x in lst1 + lst2 if x % 2 == 0)
    return "YES" if even_count_total >= len(lst1) else "NO"

def histogram(test):
    if test == '':
        return {}

    letters = test.split(' ')
    count_dict = {}

    for letter in letters:
        if letter in count_dict:
            count_dict[letter] += 1
        else:
            count_dict[letter] = 1

    max_count = max(count_dict.values())
    result = {}

    for letter, count in count_dict.items():
        if count == max_count:
            result[letter] = count

    return result

def reverse_delete(s, c):
    result = ''.join(char for char in s if char not in c)
    is_palindrome = result == result[::-1]
    return (result, is_palindrome)

def select_words(s, n):
    if not s:
        return []

    vowels = set('aeiouAEIOU')
    words = s.split()
    result = []

    for word in words:
        consonant_count = 0
        for char in word:
            if char.isalpha() and char not in vowels:
                consonant_count += 1

        if consonant_count == n:
            result.append(word)

    return result

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"

    if len(word) < 3:
        return ""

    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]

    return ""

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]

    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'

from typing import List, Optional


def longest(strings: List[str]) -> Optional[str]:
    assert type(strings) == list, "invalid inputs"
    assert all([isinstance(v, str) for v in strings]), "invalid inputs"

    if not strings:
        return None

    longest_string = strings[0]
    max_length = len(strings[0])

    for string in strings[1:]:
        if len(string) > max_length:
            longest_string = string
            max_length = len(string)

    return longest_string

def maximum(arr, k):
    if k == 0:
        return []

    sorted_arr = sorted(arr)
    return sorted(sorted_arr[-k:])

def get_odd_collatz(n):
    assert type(n) == int, "invalid inputs"
    assert n > 0, "invalid inputs"

    odd_numbers = set()
    current = n

    while current != 1:
        if current % 2 == 1:
            odd_numbers.add(current)
            current = 3 * current + 1
        else:
            current = current // 2

    odd_numbers.add(1)

    return sorted(list(odd_numbers))

def valid_date(date):
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    try:
        month = int(parts[0])
        day = int(parts[1])
        year = int(parts[2])
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if month in [1, 3, 5, 7, 8, 10, 12]:
        max_days = 31
    elif month in [4, 6, 9, 11]:
        max_days = 30
    else:  # month == 2
        max_days = 29

    if day < 1 or day > max_days:
        return False

    return True

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if char.islower() and (ord(char) - ord('a')) % 2 == 1:
                count += 1
        return count

def is_sorted(lst):
    if len(lst) <= 1:
        return True

    # Check for more than 1 duplicate of any number
    from collections import Counter
    counts = Counter(lst)
    for count in counts.values():
        if count > 2:
            return False

    # Check if sorted in ascending order
    for i in range(1, len(lst)):
        if lst[i] < lst[i-1]:
            return False

    return True

def intersection(interval1, interval2):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    start1, end1 = interval1
    start2, end2 = interval2

    intersection_start = max(start1, start2)
    intersection_end = min(end1, end2)

    if intersection_start > intersection_end:
        return "NO"

    length = intersection_end - intersection_start

    if is_prime(length):
        return "YES"
    else:
        return "NO"

def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    magnitude_sum = 0

    for num in arr:
        if num == 0:
            return 0
        elif num > 0:
            sign_product *= 1
            magnitude_sum += num
        else:
            sign_product *= -1
            magnitude_sum += abs(num)

    return magnitude_sum * sign_product

def greatest_common_divisor(a: int, b: int) -> int:
    assert type(a) == int and type(b) == int, "invalid inputs"
    assert a > 0 and b > 0, "invalid inputs"

    while b:
        a, b = b, a % b
    return a

def tri(n):
    if n == 0:
        return [1]

    result = [0] * (n + 1)
    result[0] = 1
    result[1] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            result[i] = 1 + i // 2
        else:
            result[i] = result[i - 1] + result[i - 2] + (1 + (i + 1) // 2)

    return result

def digits(n):
    product = 1
    has_odd = False

    while n > 0:
        digit = n % 10
        if digit % 2 == 1:
            product *= digit
            has_odd = True
        n //= 10

    return product if has_odd else 0

def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
                if stack:
                    return True
    return False

