def can_arrange(arr):
    largest_index = -1
    for i in range(1, len(arr)):
        if arr[i] < arr[i-1]:
            largest_index = i
    return largest_index

def largest_smallest_integers(lst):
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]

    largest_negative = max(negatives) if negatives else None
    smallest_positive = min(positives) if positives else None

    return (largest_negative, smallest_positive)

def compare_one(a, b):
    def to_float(x):
        return float(str(x).replace(",", "."))

    a_val = to_float(a)
    b_val = to_float(b)

    if a_val == b_val:
        return None
    elif a_val > b_val:
        return a
    else:
        return b

def is_equal_to_sum_even(n):
    assert type(n) == int, "invalid inputs"

    if n < 8:
        return False

    return n % 2 == 0

def special_factorial(n):
    assert type(n) == int, "invalid inputs"
    assert n > 0, "invalid inputs"

    result = 1
    for i in range(1, n + 1):
        factorial_i = 1
        for j in range(1, i + 1):
            factorial_i *= j
        result *= factorial_i

    return result

def fix_spaces(text):
    assert isinstance(text, str), "invalid inputs"

    result = ""
    i = 0

    while i < len(text):
        if text[i] == ' ':
            space_count = 0
            j = i
            while j < len(text) and text[j] == ' ':
                space_count += 1
                j += 1

            if space_count > 2:
                result += '-'
            else:
                result += '_' * space_count

            i = j
        else:
            result += text[i]
            i += 1

    return result

def file_name_check(file_name):
    if file_name.count('.') != 1:
        return 'No'

    parts = file_name.split('.')
    name_part = parts[0]
    extension = parts[1]

    if not name_part:
        return 'No'

    if not name_part[0].isalpha():
        return 'No'

    digit_count = sum(1 for char in file_name if char.isdigit())
    if digit_count > 3:
        return 'No'

    if extension not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

def sum_squares(lst):
    result = 0
    for i in range(len(lst)):
        if i % 3 == 0:
            result += lst[i] ** 2
        elif i % 4 == 0:
            result += lst[i] ** 3
        else:
            result += lst[i]
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split(" ")
    prime_length_words = []

    for word in words:
        if is_prime(len(word)):
            prime_length_words.append(word)

    return " ".join(prime_length_words)

def order_by_points(nums):
    def digit_sum(n):
        if n == 0:
            return 0
        if n < 0:
            digits = str(-n)
            return -int(digits[0]) + sum(int(d) for d in digits[1:])
        else:
            return sum(int(d) for d in str(n))

    indexed_nums = [(num, i) for i, num in enumerate(nums)]
    indexed_nums.sort(key=lambda x: (digit_sum(x[0]), x[1]))
    return [num for num, _ in indexed_nums]

def specialFilter(nums):
    count = 0
    for num in nums:
        if num > 10:
            str_num = str(abs(num))
            first_digit = int(str_num[0])
            last_digit = int(str_num[-1])
            if first_digit % 2 == 1 and last_digit % 2 == 1:
                count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    idx1 = planets.index(planet1)
    idx2 = planets.index(planet2)

    start = min(idx1, idx2)
    end = max(idx1, idx2)

    return tuple(planets[start + 1:end])

def sorted_list_sum(lst):
    filtered_list = [s for s in lst if len(s) % 2 == 0]
    return sorted(filtered_list, key=lambda x: (len(x), x))

def string_sequence(n: int) -> str:
    assert type(n) == int, "invalid inputs"
    assert n >= 0, "invalid inputs"
    return ' '.join(str(i) for i in range(n + 1))

def x_or_y(n, x, y):
    if n < 2:
        return y

    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return y

    return x

def double_the_difference(lst):
    if not lst:
        return 0

    total = 0
    for num in lst:
        if isinstance(num, (int, float)) and num == int(num) and num >= 0 and int(num) % 2 == 1:
            total += int(num) ** 2

    return total

def cycpattern_check(a, b):
    assert isinstance(a, str) and isinstance(b, str), "invalid inputs"

    if len(b) == 0:
        return True

    for i in range(len(b)):
        rotation = b[i:] + b[:i]
        if rotation in a:
            return True

    return False

def even_odd_count(num):
    assert type(num) == int, "invalid inputs"

    num_str = str(abs(num))
    even_count = 0
    odd_count = 0

    for digit_char in num_str:
        digit = int(digit_char)
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    return (even_count, odd_count)

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return abs(sides[0]**2 + sides[1]**2 - sides[2]**2) < 1e-10

def find_max(words):
    max_unique = -1
    result = ""

    for word in words:
        unique_count = len(set(word))
        if unique_count > max_unique or (unique_count == max_unique and word < result):
            max_unique = unique_count
            result = word

    return result

def count_distinct_characters(string: str) -> int:
    assert isinstance(string, str), "invalid inputs"
    return len(set(string.lower()))

def do_algebra(operator, operand):
    expression = str(operand[0])
    for i in range(len(operator)):
        expression += " " + operator[i] + " " + str(operand[i + 1])
    return eval(expression)

def solve(s):
    has_letters = any(c.isalpha() for c in s)

    if not has_letters:
        return s[::-1]

    result = ""
    for c in s:
        if c.isalpha():
            if c.islower():
                result += c.upper()
            else:
                result += c.lower()
        else:
            result += c

    return result

import hashlib

def string_to_md5(text):
    assert isinstance(text, str), "invalid inputs"

    if text == "":
        return None

    return hashlib.md5(text.encode()).hexdigest()

def generate_integers(a, b):
    start = min(a, b)
    end = max(a, b)
    result = []
    for i in range(start, end + 1):
        if i % 2 == 0:
            result.append(i)
    return result

from typing import List


def parse_music(music_string: str) -> List[int]:
    if not music_string:
        return []

    note_to_beats = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    notes = music_string.split(' ')
    return [note_to_beats[note] for note in notes]

def how_many_times(string: str, substring: str) -> int:
    if not string or not substring:
        return 0

    count = 0
    start = 0

    while True:
        pos = string.find(substring, start)
        if pos == -1:
            break
        count += 1
        start = pos + 1

    return count

from typing import List

def sort_numbers(numbers: str) -> str:
    if not numbers:
        return ""

    word_to_num = {
        'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4,
        'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9
    }

    num_to_word = {
        0: 'zero', 1: 'one', 2: 'two', 3: 'three', 4: 'four',
        5: 'five', 6: 'six', 7: 'seven', 8: 'eight', 9: 'nine'
    }

    words = numbers.split()
    nums = [word_to_num[word] for word in words]
    nums.sort()
    sorted_words = [num_to_word[num] for num in nums]

    return ' '.join(sorted_words)

def truncate_number(number: float) -> float:
    assert number > 0, "invalid inputs"
    assert isinstance(number, float), "invalid inputs"
    assert number != float("+inf"), "invalid inputs"

    return number - int(number)

def strlen(string: str) -> int:
    assert isinstance(string, str), "invalid inputs"
    return len(string)

def largest_divisor(n: int) -> int:
    assert type(n) == int, "invalid inputs"
    assert n > 1, "invalid inputs"

    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i

from typing import List


def remove_duplicates(numbers: List[int]) -> List[int]:
    assert type(numbers) == list, "invalid inputs"
    assert all(type(x) == int for x in numbers), "invalid inputs"

    count = {}
    for num in numbers:
        count[num] = count.get(num, 0) + 1

    result = []
    for num in numbers:
        if count[num] == 1:
            result.append(num)

    return result

def flip_case(string: str) -> str:
    assert type(string) == str, "invalid inputs"
    result = ""
    for char in string:
        if char.islower():
            result += char.upper()
        elif char.isupper():
            result += char.lower()
        else:
            result += char
    return result

from typing import List

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def sort_third(l: list):
    if len(l) == 0:
        return []

    third_elements = []
    for i in range(0, len(l), 3):
        third_elements.append(l[i])

    third_elements.sort()

    result = l.copy()
    third_index = 0
    for i in range(0, len(l), 3):
        result[i] = third_elements[third_index]
        third_index += 1

    return result

def fizz_buzz(n: int):
    count = 0
    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def sort_even(l: list):
    if len(l) == 0:
        return []

    even_values = []
    for i in range(0, len(l), 2):
        even_values.append(l[i])

    even_values.sort()

    result = l.copy()
    even_index = 0
    for i in range(0, len(l), 2):
        result[i] = even_values[even_index]
        even_index += 1

    return result

def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def fibonacci_generator():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    count = 0
    fib_gen = fibonacci_generator()

    while count < n:
        fib_num = next(fib_gen)
        if is_prime(fib_num):
            count += 1
            if count == n:
                return fib_num

def triples_sum_to_zero(l: list):
    assert type(l) == list, "invalid inputs"

    n = len(l)
    if n < 3:
        return False

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if l[i] + l[j] + l[k] == 0:
                    return True

    return False

def pairs_sum_to_zero(l):
    seen = set()
    for num in l:
        if -num in seen:
            return True
        seen.add(num)
    return False

def fib4(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0

    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

def is_palindrome(text: str):
    assert isinstance(text, str), "invalid inputs"
    return text == text[::-1]

def encode_shift(s: str):
    """
    returns encoded string by shifting every character by 5 in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def remove_vowels(text):
    vowels = 'aeiouAEIOU'
    return ''.join(char for char in text if char not in vowels)

def correct_bracketing(brackets: str):
    count = 0
    for bracket in brackets:
        if bracket == "<":
            count += 1
        elif bracket == ">":
            count -= 1
            if count < 0:
                return False
    return count == 0

def monotonic(l: list):
    assert type(l) == list, "invalid inputs"
    assert all(type(x) in (int, float, bool) for x in l), "invalid inputs"

    if len(l) <= 1:
        return True

    increasing = True
    decreasing = True

    for i in range(1, len(l)):
        if l[i] < l[i-1]:
            increasing = False
        if l[i] > l[i-1]:
            decreasing = False

    return increasing or decreasing

from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []

    for group in groups:
        max_depth = 0
        current_depth = 0

        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1

        result.append(max_depth)

    return result

def correct_bracketing(brackets: str):
    count = 0
    for bracket in brackets:
        if bracket == "(":
            count += 1
        elif bracket == ")":
            count -= 1
            if count < 0:
                return False
    return count == 0

def derivative(xs: list):
    if len(xs) <= 1:
        return []

    result = []
    for i in range(1, len(xs)):
        result.append(i * xs[i])

    return result

def fibfib(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b, c = 0, 0, 1
    for i in range(3, n + 1):
        next_val = a + b + c
        a, b, c = b, c, next_val

    return c

def vowels_count(s):
    assert type(s) == str, "invalid inputs"

    if not s:
        return 0

    vowels = 'aeiouAEIOU'
    count = 0

    for i, char in enumerate(s):
        if char in vowels:
            count += 1
        elif char.lower() == 'y' and i == len(s) - 1:
            count += 1

    return count

def pluck(arr):
    if not arr:
        return []

    smallest_even = None
    smallest_index = None

    for i, val in enumerate(arr):
        if val % 2 == 0:
            if smallest_even is None or val < smallest_even:
                smallest_even = val
                smallest_index = i

    if smallest_even is None:
        return []

    return [smallest_even, smallest_index]

def search(lst):
    from collections import Counter

    freq = Counter(lst)
    result = -1

    for num, count in freq.items():
        if count >= num:
            result = max(result, num)

    return result

def triangle_area(a, b, c):
    if a + b > c and a + c > b and b + c > a:
        s = (a + b + c) / 2
        area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
        return round(area, 2)
    else:
        return -1

def smallest_change(arr):
    n = len(arr)
    changes = 0

    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1

    return changes

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)

    if total_chars_lst1 <= total_chars_lst2:
        return lst1
    else:
        return lst2

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def get_prime_factors(n):
        factors = []
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.append(d)
                n //= d
            d += 1
        if n > 1:
            factors.append(n)
        return factors

    if a <= 1:
        return False

    prime_factors = get_prime_factors(a)
    return len(prime_factors) == 3

def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n == 0:
        return x == 0 or x == 1
    if x == 1:
        return True
    if x <= 0 or n <= 0:
        return False

    power = 1
    while power < x:
        power *= n

    return power == x

def iscube(a):
    if a == 0:
        return True

    if a > 0:
        cube_root = round(a ** (1/3))
        return cube_root ** 3 == a
    else:
        cube_root = -round((-a) ** (1/3))
        return cube_root ** 3 == a

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in prime_hex_digits)

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary = ""
    while decimal > 0:
        binary = str(decimal % 2) + binary
        decimal = decimal // 2

    return "db" + binary + "db"

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    assert all([isinstance(v, int) for v in numbers]), "invalid inputs"

    if not numbers:
        return (0, 1)

    total_sum = sum(numbers)
    total_product = 1
    for num in numbers:
        total_product *= num

    return (total_sum, total_product)

def is_happy(s):
    if len(s) < 3:
        return False

    for i in range(len(s) - 2):
        substring = s[i:i+3]
        if len(set(substring)) != 3:
            return False

    return True

def numerical_letter_grade(grades):
    result = []
    for gpa in grades:
        if gpa == 4.0:
            result.append('A+')
        elif gpa > 3.7:
            result.append('A')
        elif gpa > 3.3:
            result.append('A-')
        elif gpa > 3.0:
            result.append('B+')
        elif gpa > 2.7:
            result.append('B')
        elif gpa > 2.3:
            result.append('B-')
        elif gpa > 2.0:
            result.append('C+')
        elif gpa > 1.7:
            result.append('C')
        elif gpa > 1.3:
            result.append('C-')
        elif gpa > 1.0:
            result.append('D+')
        elif gpa > 0.7:
            result.append('D')
        elif gpa > 0.0:
            result.append('D-')
        else:
            result.append('E')
