def prime_length(string):
    assert type(string) == str, "invalid inputs"

    length = len(string)

    if length < 2:
        return False

    if length == 2:
        return True

    if length % 2 == 0:
        return False

    for i in range(3, int(length ** 0.5) + 1, 2):
        if length % i == 0:
            return False

    return True

def solve(N):
    digit_sum = sum(int(digit) for digit in str(N))
    return bin(digit_sum)[2:]

def add(lst):
    assert len(lst) > 0, "invalid inputs"
    assert all(type(x) == int for x in lst), "invalid inputs"

    total = 0
    for i in range(1, len(lst), 2):
        if lst[i] % 2 == 0:
            total += lst[i]
    return total

def anti_shuffle(s):
    words = s.split(' ')
    result = []
    for word in words:
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)
    return ' '.join(result)

def get_row(lst, x):
    coordinates = []

    for row_idx, row in enumerate(lst):
        row_coordinates = []
        for col_idx, value in enumerate(row):
            if value == x:
                row_coordinates.append((row_idx, col_idx))

        row_coordinates.sort(key=lambda coord: coord[1], reverse=True)
        coordinates.extend(row_coordinates)

    return coordinates

def sort_array(array):
    if len(array) == 0:
        return []

    if len(array) == 1:
        return array[:]

    first_last_sum = array[0] + array[-1]

    if first_last_sum % 2 == 1:
        return sorted(array)
    else:
        return sorted(array, reverse=True)

def encrypt(s):
    result = ""
    for char in s:
        if char.isalpha():
            shifted = ord(char) - ord('a')
            shifted = (shifted + 4) % 26
            result += chr(shifted + ord('a'))
        else:
            result += char
    return result

def next_smallest(lst):
    if len(lst) < 2:
        return None

    unique_sorted = sorted(set(lst))

    if len(unique_sorted) < 2:
        return None

    return unique_sorted[1]

def is_bored(S):
    import re
    sentences = re.split(r'[.?!]', S)
    count = 0
    for sentence in sentences:
        sentence = sentence.strip()
        if sentence.startswith('I ') or sentence == 'I':
            count += 1
    return count

def any_int(x, y, z):
    if not all(isinstance(v, int) and not isinstance(v, bool) for v in [x, y, z]):
        return False

    return x == y + z or y == x + z or z == x + y

def encode(message):
    vowels = "aeiouAEIOU"
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    result = ""
    for char in message:
        if char == " ":
            result += char
        elif char in vowels:
            result += vowel_map[char].swapcase()
        else:
            result += char.swapcase()

    return result

def skjkasdkd(lst):
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    largest_prime = max(x for x in lst if is_prime(x))
    return sum(int(digit) for digit in str(largest_prime))

def check_dict_case(dict):
    if not dict:
        return False

    keys = list(dict.keys())

    if not all(isinstance(key, str) for key in keys):
        return False

    all_lower = all(key.islower() for key in keys)
    all_upper = all(key.isupper() for key in keys)

    return all_lower or all_upper

def count_up_to(n):
    if n <= 2:
        return []

    primes = []
    for num in range(2, n):
        is_prime = True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return primes

def count_upper(s):
    assert type(s) == str, "invalid inputs"

    uppercase_vowels = {'A', 'E', 'I', 'O', 'U'}
    count = 0

    for i in range(0, len(s), 2):
        if s[i] in uppercase_vowels:
            count += 1

    return count

def closest_integer(value):
    try:
        assert isinstance(value, str)
        value = float(value)
    except:
        raise Exception("invalid inputs")
    import math
    assert not (math.isinf(value) or math.isnan(value)), "invalid inputs"

    if value >= 0:
        return int(value + 0.5)
    else:
        return int(value - 0.5)

def next_smallest_palindrome(num):
    assert isinstance(num, int), "invalid inputs"
    assert num >= 0, "invalid inputs"

    num += 1

    while True:
        s = str(num)
        if s == s[::-1]:
            return num
        num += 1

def snake_to_camel(word):
    assert isinstance(word, str), "invalid inputs"
    assert len(word) > 0, "invalid inputs"

    parts = word.split('_')
    return ''.join(part.capitalize() for part in parts)

def eulerian_num(n, m):
    if m >= n:
        return 0
    if m == 0:
        return 1

    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = 1

    for i in range(1, n + 1):
        for j in range(1, i + 1):
            dp[i][j] = (j + 1) * dp[i - 1][j] + (i - j) * dp[i - 1][j - 1]

    return dp[n][m]

def count(lst):
    assert isinstance(lst, list), "invalid inputs"
    assert all(isinstance(x, bool) for x in lst), "invalid inputs"
    return sum(lst)

def remove_Occ(s, ch):
    assert isinstance(s, str), "invalid inputs"
    assert isinstance(ch, str), "invalid inputs"
    assert len(s) > 0, "invalid inputs"
    assert len(ch) == 1, "invalid inputs"

    first_index = s.find(ch)
    if first_index == -1:
        return s

    last_index = s.rfind(ch)

    if first_index == last_index:
        return s[:first_index] + s[first_index + 1:]
    else:
        return s[:first_index] + s[first_index + 1:last_index] + s[last_index + 1:]

def common_in_nested_lists(nestedlist):
    assert isinstance(nestedlist, list), "invalid inputs"
    assert all(isinstance(item, list) for item in nestedlist), "invalid inputs"

    if not nestedlist:
        return []

    common = set(nestedlist[0])
    for lst in nestedlist[1:]:
        common = common.intersection(set(lst))

    return list(common)

def check_integer(text):
    assert isinstance(text, str), "invalid inputs"

    if not text:
        return False

    start_idx = 0
    if text[0] in ['+', '-']:
        start_idx = 1
        if len(text) == 1:
            return False

    for char in text[start_idx:]:
        if not char.isdigit():
            return False

    return True

def tuple_to_int(nums):
    assert isinstance(nums, tuple), "invalid inputs"
    assert len(nums) > 0, "invalid inputs"
    assert all(isinstance(x, int) for x in nums), "invalid inputs"
    assert all(x > 0 for x in nums), "invalid inputs"

    return int(''.join(str(x) for x in nums))

def string_to_list(string):
    assert isinstance(string, str), "invalid inputs"
    return string.split(' ')

def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        if mid % 2 == 1:
            mid -= 1

        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid

    return arr[left]

def amicable_numbers_sum(limit):
    assert isinstance(limit, int), "invalid inputs"
    assert limit >= 1, "invalid inputs"

    def sum_of_proper_divisors(n):
        if n <= 1:
            return 0
        divisors_sum = 1
        i = 2
        while i * i <= n:
            if n % i == 0:
                divisors_sum += i
                if i * i != n:
                    divisors_sum += n // i
            i += 1
        return divisors_sum

    amicable_sum = 0
    checked = set()

    for i in range(1, limit + 1):
        if i in checked:
            continue

        sum_i = sum_of_proper_divisors(i)
        sum_sum_i = sum_of_proper_divisors(sum_i)

        if i == sum_sum_i and i != sum_i:
            amicable_sum += i
            checked.add(i)
            if sum_i <= limit:
                amicable_sum += sum_i
                checked.add(sum_i)

    return amicable_sum

import math

def angle_complex(a, b):
    if a == 0 and b == 0:
        return 0
    return math.atan2(b.imag, a)

def find_length(string):
    if not string:
        return 0

    max_diff = 0
    n = len(string)

    for i in range(n):
        zeros = 0
        ones = 0
        for j in range(i, n):
            if string[j] == '0':
                zeros += 1
            else:
                ones += 1

            diff = zeros - ones
            max_diff = max(max_diff, diff)

    return max_diff

def sum(a, b):
    assert isinstance(a, int), "invalid inputs"
    assert isinstance(b, int), "invalid inputs"
    assert a > 0, "invalid inputs"
    assert b > 0, "invalid inputs"

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def get_divisors(n):
        divisors = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return set(divisors)

    divisors_a = get_divisors(a)
    divisors_b = get_divisors(b)
    common_divisors = divisors_a.intersection(divisors_b)

    return sum(common_divisors)

def magic_square_test(my_matrix):
    assert isinstance(my_matrix, list), "invalid inputs"
    assert len(my_matrix) > 0, "invalid inputs"
    assert all(isinstance(row, list) for row in my_matrix), "invalid inputs"
    assert len(my_matrix[0]) > 0, "invalid inputs"
    assert all(len(row) == len(my_matrix[0]) for row in my_matrix), "invalid inputs"
    assert all(isinstance(item, (int, float)) for row in my_matrix for item in row), "invalid inputs"

    n = len(my_matrix)
    if n != len(my_matrix[0]):
        return False

    magic_sum = sum(my_matrix[0])

    for row in my_matrix:
        if sum(row) != magic_sum:
            return False

    for col in range(n):
        if sum(my_matrix[row][col] for row in range(n)) != magic_sum:
            return False

    if sum(my_matrix[i][i] for i in range(n)) != magic_sum:
        return False

    if sum(my_matrix[i][n-1-i] for i in range(n)) != magic_sum:
        return False

    return True

def max_occurrences(nums):
    if not nums:
        return None

    frequency = {}
    for num in nums:
        frequency[num] = frequency.get(num, 0) + 1

    return max(frequency, key=frequency.get)

def reverse_vowels(str1):
    assert isinstance(str1, str), "invalid inputs"

    vowels = "aeiouAEIOU"
    chars = list(str1)
    vowel_positions = []
    vowel_chars = []

    for i, char in enumerate(chars):
        if char in vowels:
            vowel_positions.append(i)
            vowel_chars.append(char)

    vowel_chars.reverse()

    for i, pos in enumerate(vowel_positions):
        chars[pos] = vowel_chars[i]

    return ''.join(chars)

def sum_negativenum(nums):
    assert isinstance(nums, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in nums), "invalid inputs"

    return sum(x for x in nums if x < 0)

def hexagonal_num(n):
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"
    return n * (2 * n - 1)

def zero_count(nums):
    zeros = nums.count(0)
    non_zeros = len(nums) - zeros
    if non_zeros == 0:
        return float('inf')
    return zeros / non_zeros

def is_Sum_Of_Powers_Of_Two(n):
    assert isinstance(n, int), "invalid inputs"
    return n > 0

def extract_singly(test_list):
    result = set()
    for sublist in test_list:
        for item in sublist:
            result.add(item)
    return list(result)

def pancake_sort(nums):
    assert isinstance(nums, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in nums), "invalid inputs"

    if len(nums) <= 1:
        return nums

    result = nums[:]
    n = len(result)

    for curr_size in range(n, 1, -1):
        max_idx = 0
        for i in range(1, curr_size):
            if result[i] > result[max_idx]:
                max_idx = i

        if max_idx != curr_size - 1:
            if max_idx != 0:
                result[:max_idx + 1] = result[:max_idx + 1][::-1]

            result[:curr_size] = result[:curr_size][::-1]

    return result

