def is_majority(arr, n, x):
    def find_first(arr, n, x):
        left, right = 0, n - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                result = mid
                right = mid - 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return result

    def find_last(arr, n, x):
        left, right = 0, n - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                result = mid
                left = mid + 1
            elif arr[mid] < x:
                left = mid + 1
            else:
                right = mid - 1
        return result

    first = find_first(arr, n, x)
    if first == -1:
        return False

    last = find_last(arr, n, x)
    count = last - first + 1

    return count > n // 2

