def even_bit_set_number(n):
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"

    result = n
    bit_position = 0

    while (1 << bit_position) <= n or bit_position < 32:
        if bit_position % 2 == 0:
            result |= (1 << bit_position)
        bit_position += 1
        if bit_position >= 32:
            break

    return result

