def get_total_number_of_sequences(m, n):
    assert isinstance(m, int) and m > 0, "invalid inputs"
    assert isinstance(n, int) and n > 0, "invalid inputs"

    dp = {}

    def count_sequences(length, min_val):
        if length == 0:
            return 1

        if (length, min_val) in dp:
            return dp[(length, min_val)]

        total = 0
        for val in range(min_val, m + 1):
            total += count_sequences(length - 1, 2 * val)

        dp[(length, min_val)] = total
        return total

    return count_sequences(n, 1)

