def max_sum(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    # Calculate increasing subsequence sums ending at each position
    inc = [0] * n
    inc[0] = arr[0]

    for i in range(1, n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Calculate decreasing subsequence sums starting from each position
    dec = [0] * n
    dec[n-1] = arr[n-1]

    for i in range(n-2, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], arr[i] + dec[j])

    # Find maximum bitonic sum
    max_bitonic = 0
    for i in range(n):
        max_bitonic = max(max_bitonic, inc[i] + dec[i] - arr[i])

    return max_bitonic

def lps(str1):
    n = len(str1)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if str1[i] == str1[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    return dp[0][n - 1]

