def newman_prime(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def newman_shanks_williams(k):
        if k == 0:
            return 1
        if k == 1:
            return 1

        a, b = 1, 1
        for i in range(2, k + 1):
            a, b = b, 2 * b + a
        return b

    if n == 0:
        return 0

    count = 0
    k = 1

    while count < n:
        nsw = newman_shanks_williams(k)
        if is_prime(nsw):
            count += 1
            if count == n:
                return nsw
        k += 1

    return 0

