def max_sum_increasing_subseq(a, n, index, k):
    dp = [0] * n
    dp[0] = a[0]

    for i in range(1, n):
        dp[i] = a[i]
        for j in range(i):
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + a[i])

    max_sum_at_index = 0
    for i in range(index + 1):
        if a[i] < a[k]:
            max_sum_at_index = max(max_sum_at_index, dp[i])

    return max_sum_at_index + a[k]

