def set_left_most_unset_bit(n):
    assert isinstance(n, int) and n >= 0, "invalid inputs"

    if n == 0:
        return 1

    bit_position = 0
    temp = n

    while temp > 0:
        bit_position += 1
        temp >>= 1

    for i in range(bit_position - 1, -1, -1):
        if (n & (1 << i)) == 0:
            return n | (1 << i)

    return n | (1 << bit_position)

