        a, b = b, a + b

    return b

def get_max_sum(n):
    memo = {}

    def helper(n):
        if n in memo:
            return memo[n]

        if n == 0:
            return 0

        sum_parts = helper(n // 2) + helper(n // 3) + helper(n // 4) + helper(n // 5)
        result = max(sum_parts, n)
        memo[n] = result
        return result

    return helper(n)

