def cal_sum(n):
    assert isinstance(n, int), "invalid inputs"

    if n <= 0:
        return 0

    # Generate Perrin numbers
    perrin = []
    if n >= 1:
        perrin.append(3)
    if n >= 2:
        perrin.append(0)
    if n >= 3:
        perrin.append(2)

    # Generate remaining Perrin numbers using the recurrence relation
    # P(n) = P(n-2) + P(n-3)
    for i in range(3, n):
        next_perrin = perrin[i-2] + perrin[i-3]
        perrin.append(next_perrin)

    return sum(perrin)

