def sumofFactors(n):
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"

    if n == 0:
        return 0

    sum_even_factors = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i % 2 == 0:
                sum_even_factors += i
            if i != n // i and (n // i) % 2 == 0:
                sum_even_factors += n // i

    return sum_even_factors

