                combination.append(list1[j])
        result.append(combination)

    return result

def max_product(arr):
    n = len(arr)
    if n == 0:
        return 0

    # dp[i] stores the maximum product of increasing subsequence ending at index i
    dp = [0] * n

    # Initialize dp array with individual elements
    for i in range(n):
        dp[i] = arr[i]

    # Fill dp array
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] * arr[i])

    # Return the maximum product among all subsequences
    return max(dp)

