def catalan_number(num):
    assert isinstance(num, int), "invalid inputs"
    assert num >= 0, "invalid inputs"

    if num <= 1:
        return 1

    catalan = [0] * (num + 1)
    catalan[0] = 1
    catalan[1] = 1

    for i in range(2, num + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - 1 - j]

    return catalan[num]

