def sum_Of_product(n):
    assert isinstance(n, int), "invalid inputs"
    assert n >= 0, "invalid inputs"

    def binomial_coeff(n, k):
        if k > n or k < 0:
            return 0
        if k == 0 or k == n:
            return 1

        result = 1
        for i in range(min(k, n - k)):
            result = result * (n - i) // (i + 1)
        return result

    total_sum = 0
    for i in range(n):
        coeff1 = binomial_coeff(n, i)
        coeff2 = binomial_coeff(n, i + 1)
        total_sum += coeff1 * coeff2

    return total_sum

