def get_median(arr1, arr2, n):
    merged = []
    i = j = 0

    while i < n and j < n:
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1

    while i < n:
        merged.append(arr1[i])
        i += 1

    while j < n:
        merged.append(arr2[j])
        j += 1

    total_length = 2 * n
    if total_length % 2 == 0:
        return (merged[total_length // 2 - 1] + merged[total_length // 2]) / 2.0
    else:
        return float(merged[total_length // 2])

