def check_expression(exp):
    assert isinstance(exp, str), "invalid inputs"

    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}

    for char in exp:
        if char in pairs:
            stack.append(char)
        elif char in pairs.values():
            if not stack or pairs[stack.pop()] != char:
                return False

    return len(stack) == 0

