def sequence(n):
    if n == 1 or n == 2:
        return 1

    memo = [0] * (n + 1)
    memo[1] = 1
    memo[2] = 1

    for i in range(3, n + 1):
        memo[i] = memo[memo[i - 1]] + memo[i - memo[i - 1]]

    return memo[n]

