    return result

import math

def max_fill(grid, capacity):
    total_water = sum([sum(row) for row in grid])
    return math.ceil(total_water / capacity)

def select_words(s, n):
    def count_consonants(word):
        vowels = "aeiouAEIOU"
        return sum(1 for char in word if char.isalpha() and char not in vowels)

    words = s.split()
    result = [word for word in words if count_consonants(word) == n]
    return result

def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    length = len(word)

    for i in range(length - 2, 0, -1):
        if word[i] in vowels and word[i + 1:].isalpha():
            return word[i]
    return ""

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Concatenate the two strings and check if they are balanced
    combined = lst[0] + lst[1]
    return 'Yes' if is_balanced(combined) else 'No'

from typing import List, Optional

def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None
    max_length = -1
    longest_string = None
    for s in strings:
        if len(s) > max_length:
            max_length = len(s)
            longest_string = s
    return longest_string

import re
from datetime import datetime

def valid_date(date):
    if not isinstance(date, str) or len(date) == 0:
        return False

    pattern = r'^(\d{2})-(\d{2})-(\d{4})$'
    match = re.match(pattern, date)
    if not match:
        return False

    month, day, year = map(int, match.groups())

    if month < 1 or month > 12:
        return False

    days_in_month = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month != 2:
        if day < 1 or day > days_in_month[month - 1]:
            return False
    else:
        if day < 1 or day > 29:
            return False

    try:
        datetime(year, month, day)
        return True
    except ValueError:
        return False

# Example usage:
print(valid_date('03-11-2000')) # => True
print(valid_date('15-01-2012')) # => False
print(valid_date('04-0-2040'))  # => False
print(valid_date('06-04-2020')) # => True
print(valid_date('06/04/2020')) # => False

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if ord('a') <= ord(char) <= ord('z'):
                count += (ord(char) - ord('a')) % 2 == 1
        return count

def is_sorted(lst):
    if len(lst) <= 1:
        return True

    prev = lst[0]
    for num in lst[1:]:
        if num < prev:
            return False
        elif num == prev:
            return False
        prev = num
    return True

def intersection(interval1, interval2):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Find the intersection of the two intervals
    start_intersection = max(interval1[0], interval2[0])
    end_intersection = min(interval1[1], interval2[1])

    if start_intersection <= end_intersection:
        length_of_intersection = end_intersection - start_intersection + 1
        return "YES" if is_prime(length_of_intersection) else "NO"
    else:
        return "NO"

def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    sum_magnitudes = 0

    for num in arr:
        sign_product *= (1 if num > 0 else -1)
        sum_magnitudes += abs(num)

    return sign_product * sum_magnitudes

import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    # Initialize the priority queue with all starting positions
    pq = []
    for i in range(N):
        for j in range(N):
            heapq.heappush(pq, (grid[i][j], [(i, j)]))

    while pq:
        current_value, path = heapq.heappop(pq)

        if len(path) == k:
            return [grid[x][y] for x, y in path]

        last_x, last_y = path[-1]

        for dx, dy in directions:
            new_x, new_y = last_x + dx, last_y + dy
            if is_valid(new_x, new_y) and (new_x, new_y) not in path:
                new_path = path + [(new_x, new_y)]
                heapq.heappush(pq, (current_value + grid[new_x][new_y], new_path))

    return []

def greatest_common_divisor(a: int, b: int) -> int:
    while b != 0:
        a, b = b, a % b
    return a

def tri(n):
    if n < 0:
        return []

    dp = [0] * (n + 1)
    dp[1] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            dp[i] = 1 + i // 2
        else:
            dp[i] = dp[i - 1] + dp[i - 2] + dp[i + 1]

    return [dp[i] for i in range(n + 1)]

def digits(n):
    product = 1
    for digit in str(n):
        if int(digit) % 2 != 0:
            product *= int(digit)
    return product if n > 0 else 0

def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack and stack[-1] == '[':
                stack.pop()
            else:
                stack.append(char)
    return len(stack) == 0

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    last_char = txt[-1]
    return last_char.isalpha() and (len(txt) == 1 or txt[len(txt)-2] == ' ')

def compare_one(a, b):
    def to_float(x):
        try:
            return float(str(x).replace(",", "."))
        except ValueError:
            return float('nan')

    a_float = to_float(a)
    b_float = to_float(b)

    if a_float > b_float:
        return a if isinstance(a, (int, float)) else str(a)
    elif b_float > a_float:
        return b if isinstance(b, (int, float)) else str(b)
    else:
        return None

def special_factorial(n):
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        else:
            return num * factorial(num - 1)

    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)
    return result

from typing import List

def all_prefixes(string: str) -> List[str]:
    return [string[:i] for i in range(1, len(string) + 1)]

def fix_spaces(text):
    if not isinstance(text, str):
        raise ValueError("invalid inputs")

    result = []
    for char in text:
        if char == ' ':
            if len(result) > 0 and result[-1] != '_':
                result.append('_')
        else:
            result.append(char)
    return ''.join(result)

def file_name_check(file_name):
    if not isinstance(file_name, str):
        return 'No'

    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    name_part, extension_part = parts
    if not name_part or not (name_part[0].isalpha()):
        return 'No'

    digits = sum(char.isdigit() for char in name_part)
    if digits > 3:
        return 'No'

    valid_extensions = ['txt', 'exe', 'dll']
