def pancake_sort(nums):
    def flip(sublist, k):
        return sublist[:k+1][::-1] + sublist[k+1:]

    n = len(nums)
    for i in range(n-1, -1, -1):
        max_index = nums.index(max(nums[:i+1]))
        if max_index != i:
            if max_index != 0:
                nums = flip(nums, max_index)
            nums = flip(nums, i)
    return nums

