def get_total_number_of_sequences(m, n):
    def count_sequences(current, length):
        if length == 1:
            return 1
        count = 0
        for next_val in range(current * 2, m + 1):
            count += count_sequences(next_val, length - 1)
        return count

    total_count = 0
    for start in range(1, m + 1):
        total_count += count_sequences(start, n)
    return total_count

