import math

def count_binary_seq(n):
    def count_ways(pos, diff, memo):
        if (pos, diff) in memo:
            return memo[(pos, diff)]
        if pos == 2 * n:
            return 1 if diff == 0 else 0
        ways = 0
        if diff < 0 or diff > n - pos // 2 + 1:
            return 0
        ways += count_ways(pos + 1, diff + 1, memo)
        ways += count_ways(pos + 1, diff - 1, memo)
        memo[(pos, diff)] = ways
        return ways

    if n <= 0:
        return 0
    memo = {}
    return count_ways(0, 0, memo)

