def sum_Of_product(n):
    def binomial_coefficient(n, k):
        if k > n - k:
            k = n - k
        res = 1
        for i in range(k):
            res *= (n - i)
            res //= (i + 1)
        return res

    total_sum = 0
    for k in range(n + 1):
        coeff = binomial_coefficient(n, k)
        if k < n:
            next_coeff = binomial_coefficient(n, k + 1)
            total_sum += coeff * next_coeff

    return total_sum

