def largest_subset(a):
    if not isinstance(a, list) or len(a) < 2 or not all(isinstance(el, (int, float)) for el in a):
        return "invalid inputs"

    n = len(a)
    dp = [1] * n
    prev = [-1] * n

    a.sort()

    for i in range(n):
        for j in range(i):
            if a[i] % a[j] == 0:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j

    max_len = max(dp)
    index = dp.index(max_len)

    result = []
    while index != -1:
        result.append(a[index])
        index = prev[index]

    return len(result)

def get_median(arr1, arr2, n):
    merged = []
    i = 0
    j = 0

    while i < n and j < n:
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1

    while i < n:
        merged.append(arr1[i])
        i += 1

    while j < n:
        merged.append(arr2[j])
        j += 1

    mid = n // 2
    if n % 2 == 0:
        return (merged[mid - 1] + merged[mid]) / 2
    else:
        return float(merged[mid])

