def is_samepatterns(colors, patterns):
    if not (isinstance(colors, list) and isinstance(patterns, list)):
        return False

    pattern_map = {}
    for color, pattern in zip(colors, patterns):
        if pattern in pattern_map:
            if pattern_map[pattern] != color:
                return False
        else:
            pattern_map[pattern] = color

    seen_patterns = set()
    for pattern in patterns:
        if pattern in seen_patterns and pattern_map[pattern] != colors[list(seen_patterns).index(pattern)]:
            return False
        seen_patterns.add(pattern)

    return True

