    parts = date.split('-')
    if len(parts) != 3:
        return False
    if not (parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit()):
        return False
    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])
    if month < 1 or month > 12:
        return False
    if month in (1, 3, 5, 7, 8, 10, 12):
        if day < 1 or day > 31:
            return False
    elif month in (4, 6, 9, 11):
        if day < 1 or day > 30:
            return False
    else:
        if day < 1 or day > 29:
            return False
    return True

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for ch in txt:
            if ch.islower():
                order = ord(ch) - ord('a')
                if order % 2 == 1:
                    count += 1
        return count

def is_sorted(lst):
    if len(lst) <= 1:
        return True
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
    from collections import Counter
    counts = Counter(lst)
    for count in counts.values():
        if count > 2:
            return False
    return True

def intersection(interval1, interval2):
    assert len(interval1) == 2 and interval1[0] <= interval1[1], "invalid inputs"
    assert all(type(x) == int for x in interval1), "invalid inputs"
    assert len(interval2) == 2 and interval2[0] <= interval2[1], "invalid inputs"
    assert all(type(x) == int for x in interval2), "invalid inputs"

    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    if start > end:
        return "NO"

    length = end - start

    if length < 2:
        return "NO"

    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return "NO"

    return "YES"

def prod_signs(arr):
    if not arr:
        return None

    product = 1
    magnitude_sum = 0

    for num in arr:
        if num > 0:
            product *= 1
            magnitude_sum += num
        elif num < 0:
            product *= -1
            magnitude_sum += -num
        else:
            product *= 0
            magnitude_sum += 0

    return product * magnitude_sum

def tri(n):
    if n == 0:
        return [1]
    memo = {1: 3}
    def tri_rec(k):
        if k in memo:
            return memo[k]
        if k % 2 == 0:
            val = 1 + k // 2
        else:
            val = tri_rec(k - 1) + tri_rec(k - 2) + tri_rec(k + 1)
        memo[k] = val
        return val
    for i in range(1, n + 1):
        tri_rec(i)
    result = [1]
    for i in range(1, n + 1):
        result.append(memo[i])
    return result

def digits(n):
    product = 1
    has_odd = False
    while n > 0:
        digit = n % 10
        if digit % 2 == 1:
            product *= digit
            has_odd = True
        n //= 10
    return product if has_odd else 0

def is_nested(string):
    stack = []
    found_nested = False
    for ch in string:
        if ch == '[':
            stack.append(ch)
        else:
            if stack:
                stack.pop()
                if stack:
                    found_nested = True
    return found_nested

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    last_char = txt[-1]
    if not last_char.isalpha():
        return False
    if len(txt) == 1:
        return True
    second_last = txt[-2]
    return second_last == ' '

def can_arrange(arr):
    for i in range(len(arr) - 1, 0, -1):
        if arr[i] <= arr[i - 1]:
            return i
    return -1

def largest_smallest_integers(lst):
    negatives = [x for x in lst if x < 0]
    positives = [x for x in lst if x > 0]

    a = max(negatives) if negatives else None
    b = min(positives) if positives else None

    return (a, b)

def compare_one(a, b):
    def to_float(x):
        if isinstance(x, str):
            x = x.replace(',', '.')
        return float(x)

    fa = to_float(a)
    fb = to_float(b)

    if fa == fb:
        return None
    elif fa > fb:
        return a
    else:
        return b

def special_factorial(n):
    result = 1
    for i in range(1, n + 1):
        fact = 1
        for j in range(1, i + 1):
            fact *= j
        result *= fact
    return result

def all_prefixes(string: str):
    if not isinstance(string, str):
        raise AssertionError("invalid inputs")
    return [string[:i] for i in range(1, len(string) + 1)]

def fix_spaces(text):
    if not isinstance(text, str):
        raise AssertionError("invalid inputs")

    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] != ' ':
            result.append(text[i])
            i += 1
        else:
            count = 0
            while i < n and text[i] == ' ':
                count += 1
                i += 1
            if count > 2:
                result.append('-')
            else:
                result.append('_' * count)

    return ''.join(result)

def file_name_check(file_name):
    if not isinstance(file_name, str):
        return "No"

    if file_name.count('.') != 1:
        return "No"

    before_dot, after_dot = file_name.split('.')

    if not before_dot:
        return "No"

    if not before_dot[0].isalpha():
        return "No"

    digit_count = sum(c.isdigit() for c in file_name)
    if digit_count > 3:
        return "No"

    valid_extensions = {'txt', 'exe', 'dll'}
    if after_dot not in valid_extensions:
        return "No"

    return "Yes"

def sum_squares(lst):
    total = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            total += num * num
        elif i % 4 == 0:
            total += num * num * num
        else:
            total += num
    return total

def is_prime(n):
    if n < 2:
