            result.append(word)
    return " ".join(result)

def specialFilter(nums):
    count = 0
    for num in nums:
        if num > 10:
            s = str(abs(num))
            if s:
                first = int(s[0])
                last = int(s[-1])
                if first % 2 == 1 and last % 2 == 1:
                    count += 1
