        raise AssertionError("invalid inputs")
    if not all(isinstance(x, str) for x in lst):
        raise AssertionError("invalid inputs")

    filtered = [s for s in lst if len(s) % 2 == 0]
    filtered.sort(key=lambda s: (len(s), s))
