        if isinstance(num, int) and num > 0 and num % 2 == 1:
            total += num * num
    return total

def cycpattern_check(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise AssertionError("invalid inputs")
    if not b:
        return True
    n = len(b)
    for i in range(n):
        rotated = b[i:] + b[:i]
        if rotated in a:
