def int_to_mini_roman(number):
    assert type(number) == int, "invalid inputs"
    assert 1 <= number <= 1000, "invalid inputs"

    val = [
        (1000, 'm'), (900, 'cm'), (500, 'd'), (400, 'cd'),
        (100, 'c'), (90, 'xc'), (50, 'l'), (40, 'xl'),
        (10, 'x'), (9, 'ix'), (5, 'v'), (4, 'iv'),
        (1, 'i')
    ]

    result = []
    for v, symbol in val:
        while number >= v:
            result.append(symbol)
            number -= v
    return ''.join(result)

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return abs(sides[0]**2 + sides[1]**2 - sides[2]**2) < 1e-12

def find_max(words):
    max_unique = -1
    candidates = []
    for word in words:
        unique_count = len(set(word))
        if unique_count > max_unique:
            max_unique = unique_count
            candidates = [word]
        elif unique_count == max_unique:
            candidates.append(word)
    return min(candidates) if candidates else ""

def eat(number, need, remaining):
    if remaining >= need:
        total_eaten = number + need
        left = remaining - need
    else:
        total_eaten = number + remaining
        left = 0
    return [total_eaten, left]

def do_algebra(operator, operand):
    if len(operand) == 0:
        return 0
    result = operand[0]
    for i, op in enumerate(operator):
        if op == '+':
            result += operand[i + 1]
        elif op == '-':
            result -= operand[i + 1]
        elif op == '*':
            result *= operand[i + 1]
        elif op == '//':
            result //= operand[i + 1]
        elif op == '**':
            result **= operand[i + 1]
    return result

def solve(s):
    if not any(c.isalpha() for c in s):
        return s[::-1]

    result = []
    for ch in s:
        if ch.isalpha():
            if ch.islower():
                result.append(ch.upper())
            else:
                result.append(ch.lower())
        else:
            result.append(ch)
    return ''.join(result)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not isinstance(text, str):
        raise AssertionError("invalid inputs")

    if text == "":
        return None

    return hashlib.md5(text.encode()).hexdigest()

from typing import List

def parse_music(music_string: str) -> List[int]:
    mapping = {
        'o': 4,
