        if balance < 0:
            return True
    return False

import math


def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    assert isinstance(xs, list) and len(xs) > 0 and len(xs) % 2 == 0, "invalid inputs"
    assert xs[-1] != 0, "invalid inputs"
    assert all(type(x) == int for x in xs), "invalid inputs"
    dxs = [xs[i] * i for i in range(1, len(xs))]
    def func(x):
        return poly(xs, x)
    def derivative(x):
        return poly(dxs, x)
    x, tol = 0, 1e-5
    for _ in range(1000):
        fx = func(x)
        dfx = derivative(x)
        if abs(fx) < tol:
            break
        x = x - fx / dfx
    assert abs(poly(xs, x)) < tol, "invalid inputs"
    return x

def sort_third(l: list):
    result = l[:]
    divisible_by_three = [l[i] for i in range(len(l)) if i % 3 == 0]
    divisible_by_three.sort()
    idx = 0
    for i in range(len(l)):
        if i % 3 == 0:
            result[i] = divisible_by_three[idx]
            idx += 1
    return result

def sort_even(l: list):
    even_vals = sorted([l[i] for i in range(0, len(l), 2)])
    result = l[:]
    for i in range(0, len(l), 2):
        result[i] = even_vals[i // 2]
    return result

def is_prime(num: int) -> bool:
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def prime_fib(n: int):
    assert type(n) == int, "invalid inputs"
    assert 1 <= n <= 12, "invalid inputs"

    found = 0
    a, b = 0, 1
    while found < n:
        a, b = b, a + b
        if a > 1 and is_prime(a):
            found += 1
            if found == n:
                return a
    return None

from typing import List


def mean_absolute_deviation(numbers: List[float]) -> float:
    mean = sum(numbers) / len(numbers)
    absolute_differences = [abs(x - mean) for x in numbers]
    return sum(absolute_differences) / len(absolute_differences)

def triples_sum_to_zero(l: list):
    if len(l) < 3:
        return False
    l.sort()
    n = len(l)
    for i in range(n - 2):
        if i > 0 and l[i] == l[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = l[i] + l[left] + l[right]
            if total == 0:
                return True
            elif total < 0:
                left += 1
            else:
                right -= 1
    return False

def incr_list(l: list):
