def fib4(n: int):
    if n < 2:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0
    a, b, c, d = 0, 0, 2, 0
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d

def modp(n: int, p: int) -> int:
    """Return 2^n modulo p (be aware of numerics)."""
    if p == 1:
        return 0
    result = 1
    base = 2 % p
    while n > 0:
        if n & 1:
            result = (result * base) % p
        base = (base * base) % p
        n >>= 1
    return result

