def pluck(arr):
    if not arr:
        return []
    best_val = None
    best_idx = None
    for i, val in enumerate(arr):
        if val % 2 == 0:
            if best_val is None or val < best_val or (val == best_val and i < best_idx):
                best_val = val
                best_idx = i
    if best_val is None:
        return []
    return [best_val, best_idx]

def search(lst):
    from collections import Counter
    freq = Counter(lst)
    candidates = [num for num, count in freq.items() if count >= num]
    if not candidates:
        return -1
    return max(candidates)

def strange_sort_list(lst):
    if not lst:
        return []
    sorted_lst = sorted(lst)
    result = []
    left, right = 0, len(sorted_lst) - 1
    while left <= right:
        result.append(sorted_lst[left])
        left += 1
        if left <= right:
            result.append(sorted_lst[right])
            right -= 1
    return result

import math

def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return round(area, 2)

def will_it_fly(q, w):
