        return s
    result = []
    word_chars = []
    for ch in s:
        if ch == ' ':
            if word_chars:
                word_chars.sort(key=lambda c: ord(c))
                result.append(''.join(word_chars))
                word_chars = []
            result.append(' ')
        else:
            word_chars.append(ch)
    if word_chars:
        word_chars.sort(key=lambda c: ord(c))
        result.append(''.join(word_chars))
    return ''.join(result)

def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        for col_idx, val in enumerate(row):
            if val == x:
                result.append((row_idx, col_idx))
    result.sort(key=lambda t: (t[0], -t[1]))
    return result

def sort_array(array):
    if not array:
        return []
    first = array[0]
    last = array[-1]
    total = first + last
    sorted_arr = sorted(array)
    if total % 2 == 0:
        sorted_arr.reverse()
    return sorted_arr

def encrypt(s):
    if not s:
        return ""
    result = []
    for ch in s:
        base = ord('a')
        offset = (ord(ch) - base + 2 * 2) % 26
        result.append(chr(base + offset))
    return ''.join(result)

from typing import List


def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    result = []
    current_max = numbers[0]

    for num in numbers:
        if num > current_max:
            current_max = num
        result.append(current_max)

    return result

def next_smallest(lst):
    if len(lst) < 2:
        return None
    unique_sorted = sorted(set(lst))
    if len(unique_sorted) < 2:
        return None
    return unique_sorted[1]

def is_bored(S):
    if not isinstance(S, str):
        raise TypeError("invalid inputs")

    boredom_count = 0
    delimiters = ".?!"

    start = 0
    for i, char in enumerate(S):
        if char in delimiters:
            sentence = S[start:i].strip()
            if sentence.startswith("I "):
                boredom_count += 1
            start = i + 1

    if start < len(S):
        sentence = S[start:].strip()
        if sentence.startswith("I "):
            boredom_count += 1

    return boredom_count

def encode(message):
    vowels = set('aeiouAEIOU')
    result = []
    for ch in message:
        if ch == ' ':
            result.append(' ')
        elif ch.isalpha():
            if ch.lower() in vowels:
                base = ord('a') if ch.islower() else ord('A')
                offset = (ord(ch.lower()) - ord('a') + 2) % 26
                new_ch = chr(base + offset)
                result.append(new_ch.swapcase())
            else:
                result.append(ch.swapcase())
    return ''.join(result)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    primes = [x for x in lst if is_prime(x)]
    if not primes:
        return 0
    largest_prime = max(primes)
    return sum(int(d) for d in str(largest_prime))

def check_dict_case(dict):
    if not dict:
        return False
    keys = list(dict.keys())
    if not all(isinstance(k, str) for k in keys):
        return False
    lower_keys = all(k.islower() for k in keys)
    upper_keys = all(k.isupper() for k in keys)
    return lower_keys or upper_keys

def count_up_to(n):
    if n < 2:
        return []
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return [i for i in range(2, n) if is_prime[i]]

def closest_integer(value):
