    else:
        return int(value - 0.5)

def next_smallest_palindrome(num):
    if not isinstance(num, int) or num < 0:
        raise ValueError("invalid inputs")

    if num < 9:
        return num + 1
    if num == 9:
        return 11

    s = list(str(num))
    n = len(s)
    mid = n // 2
    left = mid - 1
    right = mid + 1 if n % 2 else mid

    while left >= 0 and s[left] == s[right]:
        left -= 1
        right += 1

    if left < 0 or s[left] < s[right]:
        carry = 1
        i = mid - 1
        if n % 2 == 1:
            val = int(s[mid]) + carry
            carry = val // 10
            s[mid] = str(val % 10)
            j = mid + 1
        else:
            j = mid

        while i >= 0:
            val = int(s[i]) + carry
            carry = val // 10
            s[i] = str(val % 10)
            s[j] = s[i]
            i -= 1
            j += 1
    else:
        while left >= 0:
            s[right] = s[left]
            left -= 1
            right += 1

    return int(''.join(s))

def snake_to_camel(word):
    if not isinstance(word, str) or len(word) == 0:
        raise ValueError("invalid inputs")
    parts = word.split('_')
    return ''.join(p.capitalize() for p in parts)

def eulerian_num(n, m):
    if m >= n or n == 0:
        return 0
    if m == 0:
        return 1

    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = 1
        for j in range(1, min(i - 1, m) + 1):
            dp[i][j] = (i - j) * dp[i - 1][j - 1] + (j + 1) * dp[i - 1][j]

    return dp[n][m]

