def merge_sorted_list(num1, num2, num3):
    assert isinstance(num1, list), "invalid inputs"
    assert isinstance(num2, list), "invalid inputs"
    assert isinstance(num3, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in num1), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in num2), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in num3), "invalid inputs"

    merged = []
    i = j = k = 0

    while i < len(num1) and j < len(num2) and k < len(num3):
        if num1[i] <= num2[j] and num1[i] <= num3[k]:
            merged.append(num1[i])
            i += 1
        elif num2[j] <= num1[i] and num2[j] <= num3[k]:
            merged.append(num2[j])
            j += 1
        else:
            merged.append(num3[k])
            k += 1

    while i < len(num1) and j < len(num2):
        if num1[i] <= num2[j]:
            merged.append(num1[i])
            i += 1
        else:
            merged.append(num2[j])
            j += 1

    while i < len(num1) and k < len(num3):
        if num1[i] <= num3[k]:
            merged.append(num1[i])
            i += 1
        else:
            merged.append(num3[k])
            k += 1

    while j < len(num2) and k < len(num3):
        if num2[j] <= num3[k]:
            merged.append(num2[j])
            j += 1
        else:
            merged.append(num3[k])
            k += 1

    merged.extend(num1[i:])
    merged.extend(num2[j:])
    merged.extend(num3[k:])

    return merged

def odd_Equivalent(s, n):
    length = len(s)
    odd_count = 0
    for i in range(length):
        rotated_index = (i - n) % length
        if s[rotated_index] == '1':
            odd_count += 1
    return odd_count

def remove_Occ(s, ch):
    if not isinstance(s, str) or not isinstance(ch, str):
        raise ValueError("invalid inputs")
    if len(s) == 0 or len(ch) != 1:
        raise ValueError("invalid inputs")

    first = s.find(ch)
    if first == -1:
        return s

    last = s.rfind(ch)
    if first == last:
        return s[:first] + s[first+1:]

    return s[:first] + s[first+1:last] + s[last+1:]

