    if not all(len(x) == 2 for x in list1):
        raise AssertionError("invalid inputs")
    if not all(isinstance(x[0], (int, float)) for x in list1):
        raise AssertionError("invalid inputs")
    if not all(isinstance(x[1], (int, float)) for x in list1):
        raise AssertionError("invalid inputs")

    max_product = float('-inf')
    for a, b in list1:
        product = abs(a * b)
        if product > max_product:
            max_product = product
    return max_product

def sum_of_divisors(n):
    total = 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            total += i
            if i != n // i:
                total += n // i
    return total

def amicable_numbers_sum(limit):
    assert isinstance(limit, int), "invalid inputs"
    assert limit >= 1, "invalid inputs"

    total = 0
    for a in range(2, limit + 1):
        b = sum_of_divisors(a)
        if b > a and b <= limit:
            if sum_of_divisors(b) == a:
                total += a + b
    return total

