def find_length(string):
    if not isinstance(string, str):
        raise ValueError("invalid inputs")
    if not all(c in '01' for c in string):
        raise ValueError("invalid inputs")

    n = len(string)
    max_diff = 0
    for i in range(n):
        zeros = 0
        ones = 0
        for j in range(i, n):
            if string[j] == '0':
                zeros += 1
            else:
                ones += 1
            diff = zeros - ones
            if diff > max_diff:
                max_diff = diff
    return max_diff

def sum(a, b):
    assert isinstance(a, int), "invalid inputs"
    assert isinstance(b, int), "invalid inputs"
    assert a > 0, "invalid inputs"
    assert b > 0, "invalid inputs"

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    g = gcd(a, b)
    total = 0
    i = 1
    while i * i <= g:
        if g % i == 0:
            total += i
            if i != g // i:
                total += g // i
        i += 1
    return total

