def magic_square_test(my_matrix):
    n = len(my_matrix)
    target_sum = n * (n * n + 1) // 2

    # Check rows
    for row in my_matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for j in range(n):
        col_sum = sum(my_matrix[i][j] for i in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal
    diag_sum = sum(my_matrix[i][i] for i in range(n))
    if diag_sum != target_sum:
        return False

    # Check secondary diagonal
    anti_diag_sum = sum(my_matrix[i][n - 1 - i] for i in range(n))
    if anti_diag_sum != target_sum:
        return False

    # Check that all numbers from 1 to n^2 are used exactly once
    flat = [item for row in my_matrix for item in row]
    if sorted(flat) != list(range(1, n * n + 1)):
        return False

    return True

def max_occurrences(nums):
    if not nums:
        return None
    freq = {}
    for item in nums:
        freq[item] = freq.get(item, 0) + 1
    max_item = None
    max_count = -1
    for item, count in freq.items():
        if count > max_count:
            max_count = count
            max_item = item
    return max_item

def reverse_vowels(str1):
