        raise AssertionError("invalid inputs")
    vowels = set("aeiouAEIOU")
    chars = list(str1)
    vowel_positions = [i for i, ch in enumerate(chars) if ch in vowels]
    vowel_chars = [chars[i] for i in vowel_positions]
    vowel_chars.reverse()
    for pos, ch in zip(vowel_positions, vowel_chars):
        chars[pos] = ch
    return ''.join(chars)

