def zero_count(nums):
    if not isinstance(nums, list):
        raise AssertionError("invalid inputs")
    if not all(isinstance(x, int) for x in nums):
        raise AssertionError("invalid inputs")
    if len(nums) == 0:
        raise AssertionError("invalid inputs")

    zeroes = nums.count(0)
    non_zeroes = len(nums) - zeroes
    if non_zeroes == 0:
        return 0.0
    return zeroes / non_zeroes

def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False
    while n > 0:
        if n % 2 == 1:
            n -= 1
            if n % 2 == 1:
                return False
        n //= 2
    return True

