def max_Abs_Diff(arr):
    if not isinstance(arr, (tuple, list)):
        raise AssertionError("invalid inputs")
    if len(arr) == 0:
        raise AssertionError("invalid inputs")
    if not all(isinstance(x, (int, float)) for x in arr):
        raise AssertionError("invalid inputs")

    if len(arr) == 1:
        return 0

    min_val = arr[0]
    max_val = arr[0]

    for num in arr[1:]:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    return abs(max_val - min_val)

import re

def text_lowercase_underscore(text):
    assert isinstance(text, str), "invalid inputs"
    assert len(text) > 0, "invalid inputs"
    pattern = r'^[a-z]+(_[a-z]+)*$'
    return bool(re.fullmatch(pattern, text))

def find_solution(a, b, n):
    if not (isinstance(a, int) and isinstance(b, int) and isinstance(n, int)):
        return None

    def extended_gcd(x, y):
        if y == 0:
            return x, 1, 0
        gcd, x1, y1 = extended_gcd(y, x % y)
        return gcd, y1, x1 - (x // y) * y1

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None

    x = x0 * (n // g)
    y = y0 * (n // g)

    # Adjust to get a non-negative solution if possible, but any valid integer pair is acceptable.
    # We'll return the particular solution we found.
    return (x, y)

