def find_even_pair(A):
    if not isinstance(A, list):
        raise AssertionError("invalid inputs")
    if not all(isinstance(x, int) for x in A):
        raise AssertionError("invalid inputs")

    even_count = 0
    odd_count = 0
    for num in A:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    total_pairs = (even_count * (even_count - 1)) // 2 + (odd_count * (odd_count - 1)) // 2
    return total_pairs

