def is_majority(arr, n, x):
    if not arr:
        return False
    left = 0
    right = n - 1
    first_pos = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] < x:
                first_pos = mid
                break
            else:
                right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    if first_pos == -1:
        return False
    last_pos = first_pos
    left = first_pos
    right = n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == n - 1 or arr[mid + 1] > x:
                last_pos = mid
                break
            else:
                left = mid + 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    count = last_pos - first_pos + 1
    return count > n // 2

