def even_bit_set_number(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("invalid inputs")

    mask = 0
    bit_pos = 0
    while True:
        if bit_pos % 2 == 0:
            mask |= (1 << bit_pos)
        bit_pos += 1
        if (1 << bit_pos) > n and bit_pos > 31:
            break

    return n | mask

