import math

def next_Perfect_Square(N):
    if not isinstance(N, (int, float)):
        raise AssertionError("invalid inputs")

    if N < 0:
        return 0

    root = math.isqrt(int(N))
    if root * root == N:
        root += 1
    else:
        root += 1
        while root * root <= N:
            root += 1

    return root * root

def max_sum(arr):
    n = len(arr)
    inc = [0] * n
    dec = [0] * n

    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(n - 1, i, -1):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    max_sum_val = 0
    for i in range(n):
        current = inc[i] + dec[i] - arr[i]
        if current > max_sum_val:
            max_sum_val = current

    return max_sum_val

def lps(str1):
    if not isinstance(str1, str):
        raise AssertionError("invalid inputs")

    n = len(str1)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = 1

    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if str1[i] == str1[j] and cl == 2:
                dp[i][j] = 2
            elif str1[i] == str1[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]

