def max_sub_array_sum_repeated(a, n, k):
    if k == 0:
        return 0

    def kadane(arr):
        max_ending_here = arr[0]
        max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    total_sum = sum(a)
    max_kadane = kadane(a)

    if k == 1:
        return max_kadane

    max_prefix = float('-inf')
    max_suffix = float('-inf')

    prefix_sum = 0
    for i in range(n):
        prefix_sum += a[i]
        max_prefix = max(max_prefix, prefix_sum)

    suffix_sum = 0
    for i in range(n-1, -1, -1):
        suffix_sum += a[i]
        max_suffix = max(max_suffix, suffix_sum)

    if total_sum > 0:
        return max(max_kadane, max_prefix + max_suffix + total_sum * (k - 2))
    else:
        return max(max_kadane, max_prefix + max_suffix)

