def get_max_sum(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("invalid inputs")

    memo = {}

    def dfs(x):
        if x <= 1:
            return x
        if x in memo:
            return memo[x]

        # Calculate sum of recursive calls
        total = dfs(x // 2) + dfs(x // 3) + dfs(x // 4) + dfs(x // 5)
        # Take max between current value and recursive sum
        result = max(x, total)
        memo[x] = result
        return result

    return dfs(n)

