def parabola_directrix(a, b, c):
    if not isinstance(a, (int, float)):
        raise TypeError("invalid inputs")
    if not isinstance(b, (int, float)):
        raise TypeError("invalid inputs")
    if not isinstance(c, (int, float)):
        raise TypeError("invalid inputs")

    # For a parabola y = a*x^2 + b*x + c, the directrix is y = k - 1/(4a)
    # where the vertex is at x = -b/(2a), y = c - b^2/(4a)
    # So directrix y = (c - b^2/(4a)) - 1/(4a) = c - (b^2 + 1)/(4a)
    # Multiply by 4a to avoid floating point issues in assertion
    return int(4 * a * c - (b * b + 1))

