def max_product(arr):
    if not isinstance(arr, list):
        raise AssertionError("invalid inputs")
    if not all(isinstance(x, (int, float)) for x in arr):
        raise AssertionError("invalid inputs")
    if len(arr) == 0:
        raise AssertionError("invalid inputs")

    n = len(arr)
    dp = [1.0] * n

    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] * arr[i])

    return int(max(dp))

