    if not all(isinstance(x, (int, float)) for x in arr):
        raise ValueError("invalid inputs")
    if not isinstance(n, (int, float)):
        raise ValueError("invalid inputs")

    product = 1
    for num in arr:
        product = (product * (num % n)) % n
    return int(product % n)

def check_Consecutive(l):
