def perfect_squares(a, b):
    assert isinstance(a, int), "invalid inputs"
    assert isinstance(b, int), "invalid inputs"

    start = min(a, b)
    end = max(a, b)

    result = []
    i = 1
    while i * i <= end:
        square = i * i
        if square >= start:
            result.append(square)
        i += 1
    return result

