def find_kth(arr1, arr2, k):
    if not isinstance(arr1, list) or not isinstance(arr2, list) or not isinstance(k, int):
        raise AssertionError("invalid inputs")
    if not (0 < k <= len(arr1) + len(arr2)):
        raise AssertionError("invalid inputs")

    i, j = 0, 0
    count = 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            count += 1
            if count == k:
                return arr1[i]
            i += 1
        else:
            count += 1
            if count == k:
                return arr2[j]
            j += 1

    while i < len(arr1):
        count += 1
        if count == k:
            return arr1[i]
        i += 1

    while j < len(arr2):
        count += 1
        if count == k:
            return arr2[j]
        j += 1

    return None

