def get_ludic(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("invalid inputs")

    if n == 1:
        return [1]

    ludics = list(range(1, n + 1))
    i = 1
    while i < len(ludics):
        step = ludics[i]
        remove_start = step - 1
        if remove_start >= len(ludics):
            break
        del ludics[remove_start::step]
        i += 1
    return ludics

def reverse_words(s):
