        return 0
    a.sort()
    dp = [1] * len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[i] % a[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

def get_median(arr1, arr2, n):
    if n == 0:
        return 0.0
    i, j = 0, 0
    m1, m2 = -1, -1
    for count in range(n + 1):
        m2 = m1
        if i == n:
            m1 = arr2[j]
            j += 1
        elif j == n:
            m1 = arr1[i]
            i += 1
        elif arr1[i] <= arr2[j]:
            m1 = arr1[i]
            i += 1
        else:
            m1 = arr2[j]
            j += 1
    return (m1 + m2) / 2.0

