def comb_sort(nums):
    if not isinstance(nums, list):
        raise AssertionError("invalid inputs")
    if not all(isinstance(item, (int, float)) for item in nums):
        raise AssertionError("invalid inputs")

    n = len(nums)
    gap = n
    shrink = 1.3
    sorted_flag = False

    while not sorted_flag:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted_flag = True

        i = 0
        while i + gap < n:
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                sorted_flag = False
            i += 1

    return nums

