    return total

def toggle_middle_bits(n):
    if n <= 2:
        return n
    bit_length = n.bit_length()
    if bit_length <= 2:
        return n
    mask = (1 << (bit_length - 1)) - 2
    return n ^ mask

def left_insertion(a, x):
    lo = 0
    hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

