def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False
    mapping = {}
    used = set()
    for c, p in zip(colors, patterns):
        if p in mapping:
            if mapping[p] != c:
                return False
        else:
            if c in used:
                return False
            mapping[p] = c
            used.add(c)
    return True

