def divisible_by_digits(startnum, endnum):
    assert isinstance(startnum, int), "invalid inputs"
    assert isinstance(endnum, int), "invalid inputs"
    assert startnum <= endnum, "invalid inputs"

    result = []
    for num in range(startnum, endnum + 1):
        if num == 0:
            continue
        temp = num
        valid = True
        while temp > 0:
            digit = temp % 10
            if digit == 0:
                valid = False
                break
            if num % digit != 0:
                valid = False
                break
            temp //= 10
        if valid:
            result.append(num)
    return result

