def second_smallest(numbers):
    if not isinstance(numbers, list):
        raise AssertionError("invalid inputs")
    if not all(isinstance(i, (int, float)) for i in numbers):
        raise AssertionError("invalid inputs")

    if len(numbers) < 2:
        return None

    first = float('inf')
    second = float('inf')

    for num in numbers:
        if num < first:
            second = first
            first = num
        elif first < num < second:
            second = num

    if second == float('inf'):
        return None
    return second

