def check_expression(exp):
    if not isinstance(exp, str):
        raise AssertionError("invalid inputs")

    stack = []
    matching = {')': '(', '}': '{', ']': '['}

    for char in exp:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack or stack[-1] != matching[char]:
                return False
            stack.pop()

    return len(stack) == 0

