def find_sum(arr):
    assert isinstance(arr, list), "invalid inputs"
    assert all(isinstance(x, (int, float)) for x in arr), "invalid inputs"
    seen = set()
    repeated = set()
    total = 0
    for num in arr:
        if num in seen:
            if num not in repeated:
                repeated.add(num)
                total -= num
        else:
            seen.add(num)
            total += num
    return total

