def last(arr, x):
    if not isinstance(arr, list):
        raise ValueError("invalid inputs")
    if not all(isinstance(i, (int, float)) for i in arr):
        raise ValueError("invalid inputs")
    if not all(a <= b for a, b in zip(arr, arr[1:])):
        raise ValueError("invalid inputs")
    if not isinstance(x, (int, float)):
        raise ValueError("invalid inputs")
    if x not in arr:
        raise ValueError("invalid inputs")

    low, high = 0, len(arr) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == x:
            result = mid
            low = mid + 1
        elif arr[mid] < x:
            low = mid + 1
        else:
            high = mid - 1
    return result

