    if x == y == z:
        return 3
    elif x == y or x == z or y == z:
        return 2
    else:
        return 0

def is_perfect_square(n: int) -> bool:
    if n < 0:
        return False
    if n in (0, 1):
        return True
    left, right = 1, n // 2
    while left <= right:
        mid = (left + right) // 2
        square = mid * mid
        if square == n:
            return True
        elif square < n:
            left = mid + 1
        else:
            right = mid - 1
    return False

def is_product_even(arr):
