def sequence(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("invalid inputs")

    if n <= 2:
        return 1

    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 1

    for i in range(3, n + 1):
        dp[i] = dp[dp[i - 1]] + dp[i - dp[i - 1]]

    return dp[n]

def centered_hexagonal_number(n: int) -> int:
    if not isinstance(n, int) or n <= 0:
        raise ValueError("invalid inputs")
    return 3 * n * (n - 1) + 1

