def is_undulating(n):
    if not isinstance(n, int) or n < 0:
        return False
    s = str(n)
    if len(s) < 3:
        return False
    pattern = s[0] + s[1]
    expected = (pattern * ((len(s) // 2) + 1))[:len(s)]
    return s == expected

