def divisor(n):
    if not isinstance(n, int) or n <= 0:
        raise ValueError("invalid inputs")
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i == n // i:
                count += 1
            else:
                count += 2
    return count

