        raise ValueError("invalid inputs")
    if len(numbers) == 0:
        raise ValueError("invalid inputs")
    if not all(isinstance(item, (int, float)) for item in numbers):
        raise ValueError("invalid inputs")

    product = 1
    for num in numbers:
        product *= num
    return product / len(numbers)

def decimal_to_binary(n):
    if n == 0:
        return "0"
    binary = ""
    while n > 0:
        binary = str(n % 2) + binary
        n //= 2
    return binary

def choose_num(x, y):
