    if (y - 1) >= x:
        return y - 1
    return -1

def rounded_avg(n, m):
    if n > m:
        return -1
    total = sum(range(n, m + 1))
    count = m - n + 1
    avg = round(total / count)
    return bin(avg)

def unique_digits(x):
    def has_no_even_digit(n):
        while n > 0:
            digit = n % 10
            if digit % 2 == 0:
                return False
            n //= 10
        return True

    result = [num for num in x if has_no_even_digit(num)]
    result.sort()
    return result

def f(n):
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        else:
            result = 1
            for i in range(2, x + 1):
                result *= i
            return result

    def sum_to(x):
        return x * (x + 1) // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to(i))

    return result

def even_odd_palindrome(n):
    def is_palindrome(x):
        return str(x) == str(x)[::-1]

    even_count = 0
    odd_count = 0

    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def count_nums(arr):
    def sum_of_digits(num):
        if num < 0:
            return -int(str(num)[1]) + sum(int(digit) for digit in str(num)[2:])
        else:
            return sum(int(digit) for digit in str(num))

    return sum(1 for x in arr if sum_of_digits(x) > 0)

def move_one_ball(arr):
