    n = len(arr)
    sorted_arr = sorted(arr)

    for i in range(n):
        if arr[i:] + arr[:i] == sorted_arr:
            return True

    return False

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into words
    words = test.split(" ")

    # Initialize a dictionary to count occurrences of each letter
    counts = {}

    # Count each letter's occurrences
    for word in words:
        if word != "":
            if word in counts:
                counts[word] += 1
            else:
                counts[word] = 1

    # Find the maximum occurrence count
    max_count = max(counts.values()) if counts else 0

    # Create a dictionary of letters with the maximum occurrence count
    result = {letter: count for letter, count in counts.items() if count == max_count}

    return result

def reverse_delete(s, c):
    # Remove all characters in s that are present in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result string is a palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

def minSubArraySum(nums):
    min_sum = float('inf')
    current_sum = 0

    for num in nums:
        current_sum += num
        if current_sum < min_sum:
            min_sum = current_sum
        if current_sum > 0:
            current_sum = 0

    return min_sum

def max_fill(grid, capacity):
