def find_solution(a, b, n):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    if n % gcd(a, b) != 0:
        return None

    # Extended Euclidean Algorithm to find one solution
    def extended_gcd(x, y):
        if x == 0:
            return (y, 0, 1)
        gcd, x1, y1 = extended_gcd(y % x, x)
        return (gcd, y1 - (y // x) * x1, x1)

    gcd, x0, y0 = extended_gcd(a, b)
    scale = n // gcd
    return (x0 * scale, y0 * scale)

