def max_sum(arr):
    n = len(arr)

    # Initialize increasing and decreasing sum arrays
    inc = [0] * n
    dec = [0] * n

    # Fill the increasing sum array
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # Fill the decreasing sum array
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # Find the maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum

