def newman_prime(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    count = 0
    i = 1
    while True:
        newman_num = (2 ** i) - 1
        if is_prime(newman_num):
            count += 1
            if count == n + 1:
                return newman_num
        i += 1

