def max_sum_increasing_subseq(a, n, index, k):
    # Initialize the dp array where dp[i] stores the maximum sum of increasing subsequence ending with a[i]
    dp = [0 for i in range(n)]

    # The maximum sum of increasing subsequence ending with the first element is the element itself
    dp[0] = a[0]

    # Fill the dp array for elements up to the given index
    for i in range(1, index + 1):
        mxm = 0
        for j in range(i):
            if a[i] > a[j] and dp[j] > mxm:
                mxm = dp[j]
        dp[i] = a[i] + mxm

    # Fill the dp array for elements from k to the end of the array
    for i in range(k, n):
        mxm = 0
        for j in range(i):
            if a[i] > a[j] and dp[j] > mxm:
                mxm = dp[j]
        dp[i] = a[i] + mxm

    # Find the maximum sum of increasing subsequence that includes the kth element
    ans = -32768
    for i in range(index, k + 1):
        if dp[i] > ans:
            ans = dp[i]

    return ans

