def find_kth(arr1, arr2, k):
    # Ensure arr1 is the smaller array
    if len(arr1) > len(arr2):
        return find_kth(arr2, arr1, k)

    # If arr1 is empty, return the k-th element from arr2
    if not arr1:
        return arr2[k - 1]

    # If k is 1, return the smaller first element of both arrays
    if k == 1:
        return min(arr1[0], arr2[0])

    # Divide k into two parts
    i = min(len(arr1), k // 2)
    j = min(len(arr2), k // 2)

    # Compare the elements at the divided positions and recurse
    if arr1[i - 1] < arr2[j - 1]:
        return find_kth(arr1[i:], arr2, k - i)
    else:
        return find_kth(arr1, arr2[j:], k - j)

