def comb_sort(nums):
    def get_next_gap(gap):
        gap = int(gap / 1.3)
        if gap < 1:
            return 1
        return gap

    n = len(nums)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False

        for i in range(n - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                swapped = True

    return nums

def power_base_sum(base, power):
