def find_first_occurrence(A, x):
    low, high = 0, len(A) - 1
    result = -1

    while low <= high:
        mid = (low + high) // 2

        if A[mid] == x:
            result = mid
            high = mid - 1
        elif A[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return result

def left_insertion(a, x):
    low, high = 0, len(a)
    while low < high:
        mid = (low + high) // 2
        if a[mid] < x:
            low = mid + 1
        else:
            high = mid
    return low

