    return count

def check_expression(exp):
    stack = []

    for char in exp:
        if char in ["(", "{", "["]:
            stack.append(char)
        else:
            if not stack:
                return False
            current_char = stack.pop()
            if (char == ")" and current_char != "(") or \
               (char == "}" and current_char != "{") or \
               (char == "]" and current_char != "["):
                return False

    return len(stack) == 0

