    # Count the occurrences of each element in the list
    for num in arr:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Calculate the sum of elements that appear only once
    total_sum = sum(num for num, count in frequency.items() if count == 1)

    return total_sum

