def sequence(n):
    if n == 1:
        return 1

    p = [0] * (n + 1)
    p[1], p[2] = 1, 1

    for i in range(3, n + 1):
        p[i] = p[p[i - 1]] + p[i - p[i - 1]]

    return p[n]

