def f(n):
    def factorial(x):
        return x * factorial(x - 1) if x > 1 else 1

    def sum_to_x(x):
        return x * (x + 1) // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_x(i))

    return result

