def file_name_check(file_name):
    if not isinstance(file_name, str):
        raise ValueError("Invalid input: file_name must be a string")

    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    prefix, extension = parts

    if not prefix or not prefix[0].isalpha():
        return 'No'

    if not any(extension == ext for ext in ['txt', 'exe', 'dll']):
        return 'No'

    digit_count = sum(c.isdigit() for c in file_name)
    if digit_count > 3:
        return 'No'

    return 'Yes'

def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)

def specialFilter(nums):
    def is_odd_and_greater_than_10(num):
        if num <= 10:
            return False
        digits = [int(d) for d in str(abs(num))]
        return all(d % 2 != 0 for d in digits)

    return sum(is_odd_and_greater_than_10(num) for num in nums)

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    count += 1
    return count

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    if planet1 not in planets or planet2 not in planets:
        return ()
    index1, index2 = planets.index(planet1), planets.index(planet2)
    if index1 > index2:
        index1, index2 = index2, index1
    return tuple(planets[index1 + 1:index2])

def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise.

    Examples:
    for x_or_y(7, 34, 12) == 34
    for x_or_y(15, 8, 5) == 5

    """
    assert type(n) == int, "invalid inputs" # $_CONTRACT_$

    return x if is_prime(n) else y

def cycpattern_check(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise ValueError("Invalid inputs")

    for i in range(len(b)):
        rotated_b = b[i:] + b[:i]
        if rotated_b in a:
            return True
    return False

def even_odd_count(num):
    num = abs(num)
    count_even = sum(1 for digit in str(num) if int(digit) % 2 == 0)
    count_odd = sum(1 for digit in str(num) if int(digit) % 2 != 0)
    return (count_even, count_odd)

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return sides[2]**2 == sides[0]**2 + sides[1]**2

def find_max(words):
    max_word = ""
    max_unique_chars = 0
    for word in words:
        unique_chars = len(set(word))
        if unique_chars > max_unique_chars or (unique_chars == max_unique_chars and word < max_word):
            max_word = word
            max_unique_chars = unique_chars
    return max_word

def eat(number, need, remaining):
    if number + need > remaining:
        return [number + remaining, 0]
    else:
        return [number + need, remaining - need]

def do_algebra(operator, operand):
    expression = str(operand[0])
    for op, num in zip(operator, operand[1:]):
        expression += f" {op} {num}"
    return eval(expression)

def solve(s):
    if any(c.isalpha() for c in s):
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        return s[::-1]

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()

def how_many_times(string: str, substring: str) -> int:
    count = 0
    start = 0
    while True:
        start = string.find(substring, start)
        if start == -1:
            break
        count += 1
        start += 1
    return count

def largest_divisor(n: int) -> int:
    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return ''.join(char.lower() if char.isupper() else char.upper() for char in string)

from typing import List


def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

import math

def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])

def find_zero(xs: list):
    assert isinstance(xs, list) and len(xs) > 0 and len(xs) % 2 == 0, "invalid inputs"
    assert xs[-1] != 0, "invalid inputs"
    assert all(type(x) == int for x in xs), "invalid inputs"
    dxs = [xs[i] * i for i in range(1, len(xs))]
    def func(x):
        return poly(xs, x)
    def derivative(x):
        return poly(dxs, x)
    x, tol = 0, 1e-5
    for _ in range(1000):
        fx = func(x)
        dfx = derivative(x)
        if abs(fx) < tol:
            break
        x = x - fx / dfx
    assert abs(poly(xs, x)) < tol, "invalid inputs"
    return round(x, 2)

def decode_cyclic(s: str) -> str:
    groups = [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]
    groups = [(group[-1] + group[:-1]) if len(group) == 3 else group for group in groups]
    return "".join(groups)

def pairs_sum_to_zero(l):
    seen = set()
    for num in l:
        if -num in seen:
            return True
        seen.add(num)
    return False

def fib4(n: int):
    if n < 2:
        return 0
    elif n == 2:
        return 2
    a, b, c, d = 0, 0, 2, 0
    for _ in range(3, n + 1):
        a, b, c, d = b, c, d, a + b + c + d
    return d

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def correct_bracketing(brackets: str):
    balance = 0
    for bracket in brackets:
        if bracket == '<':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    assert isinstance(n, int), "invalid inputs"
    assert n > 1 and not is_prime(n), "invalid inputs"

    largest_factor = None
    for i in range(2, int(n ** 0.5) + 1):
        while n % i == 0:
            largest_factor = i
            n //= i
    if n > 1:
        largest_factor = n
    return largest_factor

def correct_bracketing(brackets: str):
    balance = 0
    for bracket in brackets:
        if bracket == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        a, b, c = 0, 0, 1
        for _ in range(3, n + 1):
            a, b, c = b, c, a + b + c
        return c

def circular_shift(x, shift):
    digits = str(x)
    n = len(digits)
    if shift > n:
        return digits[::-1]
    else:
        shift %= n
        return digits[-shift:] + digits[:-shift]

def pluck(arr):
    if not arr:
        return []

    smallest_even = float('inf')
    index_of_smallest_even = -1

    for i, value in enumerate(arr):
        if value % 2 == 0 and value < smallest_even:
            smallest_even = value
            index_of_smallest_even = i

    if smallest_even == float('inf'):
        return []

    return [smallest_even, index_of_smallest_even]

def search(lst):
    from collections import Counter

    freq = Counter(lst)
    max_val = -1

    for num, count in freq.items():
        if num <= count and num > max_val:
            max_val = num

    return max_val

def strange_sort_list(lst):
    sorted_lst = sorted(lst)
    result = []
    while sorted_lst:
        if sorted_lst:
            result.append(sorted_lst.pop(0))
        if sorted_lst:
            result.append(sorted_lst.pop())
    return result

def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
    return round(area, 2)

def smallest_change(arr):
    left = 0
    right = len(arr) - 1
    changes = 0

    while left < right:
        if arr[left] != arr[right]:
            changes += 1
        left += 1
        right -= 1

    return changes

def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, 100) if is_prime(i)]

    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_simple_power(x, n):
    if x < 1 or n < 1:
        return False
    if n == 1:
        return x == 1
    power = 1
    while power < x:
        power *= n
    return power == x

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in prime_hex_digits)

def decimal_to_binary(decimal):
    if not isinstance(decimal, int) or decimal < 0:
        raise ValueError("Invalid input")

    binary = bin(decimal)[2:]
    return f"db{binary}db"

def is_happy(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i] == s[i + 2] or s[i + 1] == s[i + 2]:
            return False
    return True

def numerical_letter_grade(grades):
    letter_grades = []
    for gpa in grades:
        if gpa == 4.0:
            letter_grades.append('A+')
        elif gpa > 3.7:
            letter_grades.append('A')
        elif gpa > 3.3:
            letter_grades.append('A-')
        elif gpa > 3.0:
            letter_grades.append('B+')
        elif gpa > 2.7:
            letter_grades.append('B')
        elif gpa > 2.3:
            letter_grades.append('B-')
        elif gpa > 2.0:
            letter_grades.append('C+')
        elif gpa > 1.7:
            letter_grades.append('C')
        elif gpa > 1.3:
            letter_grades.append('C-')
        elif gpa > 1.0:
            letter_grades.append('D+')
        elif gpa > 0.7:
            letter_grades.append('D')
        elif gpa > 0.0:
            letter_grades.append('D-')
