def starts_one_ends(n):
    """
    Given a positive integer n, return the count of the numbers of n-digit
    positive integers that start or end with 1.
    """
    if n == 1:
        return 1
    else:
        return 2 * (10 ** (n - 1)) - 10 ** (n - 2)

def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        for j, value in enumerate(row[::-1]):
            if value == x:
                result.append((i, len(row) - 1 - j))
    return sorted(result)

def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            shift = (2 * 2) % 26
            new_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            result.append(new_char)
        else:
            result.append(char)
    return ''.join(result)

def next_smallest(lst):
    if len(lst) < 2:
        return None
    unique_lst = sorted(set(lst))
    return unique_lst[1] if len(unique_lst) > 1 else None

def any_int(x, y, z):
    if not all(isinstance(v, int) for v in [x, y, z]):
        return False
    return x + y == z or x + z == y or y + z == x

def encode(message):
    vowels = 'aeiou'
    shifted_vowels = {v: chr((ord(v) - 97 + 2) % 26 + 97) for v in vowels}
    shifted_vowels.update({v.upper(): shifted_vowels[v].upper() for v in vowels})

    return ''.join(shifted_vowels.get(ch, ch).swapcase() for ch in message)

def skjkasdkd(lst):
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    largest_prime = max((x for x in lst if is_prime(x)), default=0)
    return sum(int(digit) for digit in str(largest_prime))

def count_up_to(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = []
    for i in range(2, n):
        if is_prime(i):
            primes.append(i)
    return primes

def closest_integer(value):
    try:
        value = float(value)
    except ValueError:
        raise Exception("invalid inputs")

    if value > 0:
        return int(math.floor(value + 0.5))
    else:
        return int(math.ceil(value - 0.5))

def next_smallest_palindrome(num):
    if num < 0:
        raise ValueError("Number must be non-negative")

    for i in range(num + 1, 2 * num + 2):
        if str(i) == str(i)[::-1]:
            return i

def eulerian_num(n, m):
    if m >= n or n == 0:
        return 0
    if m == 0:
        return 1
    return ((n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m))

