def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    left, right = 0, n - 1

    while left < right:
        mid = left + (right - left) // 2

        # Check if the mid is at the single element
        if mid % 2 == 1:
            mid -= 1

        # If the pair is not equal, the single element is on the left side
        if arr[mid] != arr[mid + 1]:
            right = mid
        else:
            left = mid + 2

    return arr[left]

def max_product_tuple(list1):
    # Calculate the absolute product of each tuple pair and find the maximum
    return max([abs(a * b) for a, b in list1])

def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        return sum(i for i in range(1, n) if n % i == 0)

    total = 0
    for num in range(2, limit + 1):
        div_sum = sum_of_divisors(num)
        if div_sum > num and sum_of_divisors(div_sum) == num:
            total += num

    return total

import math

def angle_complex(a, b):
    if not (isinstance(a, (int, float)) or isinstance(b, complex) or isinstance(b, float)):
        raise ValueError("Invalid inputs")
    if b.real != 0:
        raise ValueError("Invalid inputs")

    return math.atan2(b.imag, a)

def find_length(s):
    max_diff = 0
    current_diff = 0

    for char in s:
        if char == '0':
            current_diff += 1
        else:
            current_diff -= 1

        if current_diff < 0:
            current_diff = 0

        max_diff = max(max_diff, current_diff)

    return max_diff

def sum(a, b):
    total = 0
    for i in range(1, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            total += i
    return total

def magic_square_test(my_matrix):
    n = len(my_matrix)
    magic_sum = sum(my_matrix[0])

    # Check rows and columns
    for i in range(n):
        if sum(my_matrix[i]) != magic_sum or sum(my_matrix[j][i] for j in range(n)) != magic_sum:
            return False

    # Check diagonals
    if sum(my_matrix[i][i] for i in range(n)) != magic_sum or sum(my_matrix[i][n-1-i] for i in range(n)) != magic_sum:
        return False

    return True

def max_occurrences(nums):
    if not nums:
        return None

    frequency = {}
    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_count = max(frequency.values())
    max_items = [num for num, count in frequency.items() if count == max_count]

    return max_items[0]

def reverse_vowels(str1):
    vowels = 'aeiouAEIOU'
    str_list = list(str1)
    i, j = 0, len(str_list) - 1

    while i < j:
        if str_list[i] not in vowels:
            i += 1
        elif str_list[j] not in vowels:
            j -= 1
        else:
            str_list[i], str_list[j] = str_list[j], str_list[i]
            i += 1
            j -= 1

    return ''.join(str_list)

