import math

def zero_count(nums):
    total_nums = len(nums)
    zero_count = nums.count(0)
    non_zero_count = total_nums - zero_count
    if non_zero_count == 0:
        return 0.0
    ratio = zero_count / non_zero_count
    return round(ratio, 6)

def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False
    while n > 1:
        if n % 2 == 1:
            return False
        n //= 2
    return True

import math

def circle_circumference(r):
    if not isinstance(r, int) or r <= 0:
        raise ValueError("invalid inputs")
    return 2 * math.pi * r

def extract_singly(test_list):
    res = []
    for sub in test_list:
        res.extend(sub)
    return set(res)

def pancake_sort(nums):
    def flip(sublist, k):
        sublist[:k+1] = reversed(sublist[:k+1])

    n = len(nums)
    for i in range(n, 1, -1):
        max_index = nums.index(max(nums[:i]))
        if max_index != i - 1:
            flip(nums, max_index)
            flip(nums, i - 1)
    return nums

def find_solution(a, b, n):
    for x in range(n // a + 1):
        if (n - a * x) % b == 0:
            y = (n - a * x) // b
            return (x, y)
    return None

def sum_series(n):
    if not isinstance(n, int):
        raise ValueError("invalid inputs")

    return sum(n - 2 * i for i in range(n // 2 + 1))

