def is_woodall(x):
    assert isinstance(x, (int, float)), "invalid inputs"
    if x < 1:
        return False
    n = int(x)
    if n % 2 == 0:
        return False
    k = 0
    while n > 1:
        if n % 2 != 0 or n & 1 != (k + 1):
            return False
        n >>= 1
        k += 1
    return True

def check_type(test_tuple):
