def get_total_number_of_sequences(m, n):
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = i

    for i in range(2, n + 1):
        for j in range(1, m + 1):
            dp[j][i] = sum(dp[k][i - 1] for k in range(j // 2, j + 1))

    return dp[m][n]

