def shell_sort(my_list):
    n = len(my_list)
    gap = n // 2

    while gap > 0:
        for index in range(gap, n):
            temp_value = my_list[index]
            position = index

            while position >= gap and my_list[position - gap] > temp_value:
                my_list[position] = my_list[position - gap]
                position -= gap

            my_list[position] = temp_value
        gap //= 2

    return my_list

