def comb_sort(nums):
    shrink_factor = 1.3
    gap = len(nums)
    sorted = False

    while not sorted:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            sorted = True

        index = 0
        while index + gap < len(nums):
            if nums[index] > nums[index + gap]:
                nums[index], nums[index + gap] = nums[index + gap], nums[index]
                sorted = False
            index += 1
    return nums

def add_dict_to_tuple(test_tup, test_dict):
