    return res

def maxAverageOfPath(cost):
    n = len(cost)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = cost[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j-1] + cost[i][j]
            elif j == 0:
                dp[i][j] = dp[i-1][j] + cost[i][j]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + cost[i][j]

    total_cost = dp[n-1][n-1]
    num_cells = n * n
    return total_cost / num_cells

def extract_quotation(text1):
    result = []
    i = 0
    while i < len(text1):
        if text1[i] == '"':
            j = i + 1
            while j < len(text1) and text1[j] != '"':
                j += 1
            result.append(text1[i+1:j])
            i = j + 1
        else:
            i += 1
    return result

