def find_first_occurrence(A, x):
    low = 0
    high = len(A) - 1
    result = -1

    while low <= high:
        mid = (low + high) // 2

        if A[mid] == x:
            result = mid
            high = mid - 1
        elif A[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return result

def toggle_middle_bits(n):
    if n < 3:
        return n

    length = len(bin(n)) - 2
    mask = (1 << (length - 1)) - 1
    return n ^ mask

def left_insertion(arr, target):
    low = 0
    high = len(arr)

    while low < high:
        mid = (low + high) // 2
        if arr[mid] < target:
            low = mid + 1
        else:
            high = mid

    return low

