def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for color, pattern in zip(colors, patterns):
        if color not in color_to_pattern and pattern not in pattern_to_color:
            color_to_pattern[color] = pattern
            pattern_to_color[pattern] = color
        elif (color in color_to_pattern and color_to_pattern[color] != pattern) or \
             (pattern in pattern_to_color and pattern_to_color[pattern] != color):
            return False

    return True

