def is_decimal(num):
    if not isinstance(num, str):
        raise ValueError("Invalid input: expected a string")

    parts = num.split('.')
    if len(parts) != 2:
        return False

    integer_part = parts[0]
    decimal_part = parts[1]

    if not integer_part.isdigit() or not decimal_part.isdigit():
        return False

    if len(decimal_part) != 2:
        return False

    return True

