def check_expression(exp):
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in exp:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or mapping[char] != stack.pop():
                return False

    return not stack

