import math

def volume_sphere(r):
    if not isinstance(r, (int, float)) or r <= 0:
        raise ValueError("invalid inputs")
    return (4/3) * math.pi * r**3

def sequence(n):
    if n == 1 or n == 2:
        return 1
    else:
        return sequence(sequence(n - 1)) + sequence(n - sequence(n - 1))

